// Package uint256 implements 256-bit unsigned integer arithmetic.
//
// This package provides a Uint type that represents a 256-bit unsigned integer,
// stored as four uint64 values in little-endian order. It includes arithmetic
// operations with overflow detection, which are essential for safe token
// calculations in DeFi protocols.
//
// The implementation is optimized for gas efficiency while maintaining
// compatibility with Ethereum's uint256 semantics, ensuring consistent
// behavior across different blockchain environments.
//
// All operations that may overflow return both the result and an overflow flag,
// allowing calling code to handle overflow conditions appropriately.
package uint256

// REF: https://github.com/Uniswap/v3-core/blob/main/contracts/libraries/FullMath.sol

// fullmath implements Uniswap V3's FullMath library.
//
// This library provides advanced fixed-point math operations that are essential
// for Uniswap V3's tick math and liquidity calculations. It enables precise
// calculations of (a * b / denominator) with full 512-bit intermediate precision.
//
// NOTE: Unlike other arithmetic functions in the uint256 package that return errors,
// functions in this file panic on invalid inputs to maintain behavioral compatibility
// with the original Solidity implementation which uses require() statements.
//
// This design choice is intentional because:
// 1. These functions are typically used in hot paths where error handling would add overhead
// 2. Invalid inputs (like zero denominator) represent programming errors, not runtime conditions
// 3. Staying close to the Solidity implementation makes protocol porting more reliable
//
// If you need error-returning versions, wrap these functions with appropriate error handling.
package uint256

var MAX_UINT256_FROM_DECIMAL *Uint

func init() {
	MAX_UINT256_FROM_DECIMAL = MustFromDecimal(MAX_UINT256)
}

// MulDiv calculates (a * b) / denominator with full 512-bit intermediate precision.
// Panics if denominator is zero or if the result overflows 256 bits.
func MulDiv(a, b, denominator *Uint) *Uint {
	if denominator.IsZero() {
		panic("denominator must be greater than 0")
	}

	// 512-bit product (8 limbs of 64 bits)
	p := umul(a, b)

	if (p[4] | p[5] | p[6] | p[7]) == 0 {
		var lo Uint
		lo[0], lo[1], lo[2], lo[3] = p[0], p[1], p[2], p[3]
		return new(Uint).Div(&lo, denominator)
	}

	// optional early overflow check:
	// If hi >= denominator then floor((hi*2^256 + lo) / denominator) >= 2^256, which is overflow.
	{
		var hi Uint
		hi[0], hi[1], hi[2], hi[3] = p[4], p[5], p[6], p[7]
		if denominator.Lte(&hi) {
			panic("overflow: denominator(" + denominator.ToString() + ") must be greater than hi(" + hi.ToString() + ")")
		}
	}

	// perform 512 / 256 division
	// udivrem stores quotient into `quot` (len(u) - len(d) + 1 words)
	// we pass 8 words to be safe.
	var quot [8]uint64
	udivrem(quot[:], p[:], denominator) // ignore remainder

	if (quot[4] | quot[5] | quot[6] | quot[7]) != 0 {
		panic("uint256: MulDiv overflow (high quotient words non-zero)")
	}

	// return lower 256 bits of quotient
	var z Uint
	copy(z[:], quot[:4])
	return &z
}

// MulDivRoundingUp calculates ceil((a * b) / denominator) with full 512-bit intermediate precision.
// Panics if denominator is zero or if the result overflows 256 bits.
func MulDivRoundingUp(a, b, denominator *Uint) *Uint {
	result := MulDiv(a, b, denominator)

	// Check if there's a remainder
	mulModResult := new(Uint).MulMod(a, b, denominator)

	// If there's no remainder, return the result as-is
	if mulModResult.IsZero() {
		return result
	}

	// Add 1 to round up, but check for overflow
	if result.Eq(MAX_UINT256_FROM_DECIMAL) {
		panic("overflow: result(" + result.ToString() + ") + 1 would exceed MAX_UINT256")
	}

	return result.Add(result, &Uint{1, 0, 0, 0})
}

// DivRoundingUp calculates ceil(x / y) and returns the result.
// Panics if y is zero.
func DivRoundingUp(x, y *Uint) *Uint {
	div := new(Uint).Div(x, y)
	mod := new(Uint).Mod(x, y)
	return new(Uint).Add(div, gt(mod, &Uint{0, 0, 0, 0}))
}

// gt returns One() if x > y, otherwise returns Zero().
func gt(x, y *Uint) *Uint {
	if x.Gt(y) {
		return &Uint{1, 0, 0, 0}
	}
	return &Uint{0, 0, 0, 0}
}

package uint256

import (
	"errors"
	"math/bits"
	"strconv"
)

const (
	MAX_UINT64  = ^uint64(0)
	MAX_UINT256 = "115792089237316195423570985008687907853269984665640564039457584007913129639935"
)

var ErrBig256Range = errors.New("decimal number > 256 bits")

var (
	zero  = Uint{0, 0, 0, 0}
	one   = Uint{1, 0, 0, 0}
	two   = Uint{2, 0, 0, 0}
	three = Uint{3, 0, 0, 0}
)

// Uint represents a 256-bit unsigned integer.
// It is stored as an array of 4 uint64 in little-endian order,
// where arr[0] is the least significant and arr[3] is the most significant.
type Uint [4]uint64

// NewUint returns a new Uint initialized with the given uint64 value.
func NewUint(val uint64) *Uint {
	return &Uint{val, 0, 0, 0}
}

// NewUintFromInt64 returns a new Uint initialized with the given int64 value.
// Panics if val is negative.
func NewUintFromInt64(val int64) *Uint {
	if val < 0 {
		panic("val is negative")
	}
	return &Uint{uint64(val), 0, 0, 0}
}

// Zero returns a new Uint with value 0.
func Zero() *Uint {
	return &Uint{0, 0, 0, 0}
}

// One returns a new Uint with value 1.
func One() *Uint {
	return &Uint{1, 0, 0, 0}
}

// SetAllOne sets z to the maximum 256-bit value (all bits set to 1) and returns z.
func (z *Uint) SetAllOne() *Uint {
	z[3], z[2], z[1], z[0] = MAX_UINT64, MAX_UINT64, MAX_UINT64, MAX_UINT64
	return z
}

// Set sets z to x and returns z.
func (z *Uint) Set(x *Uint) *Uint {
	*z = *x
	return z
}

// SetOne sets z to 1 and returns z.
func (z *Uint) SetOne() *Uint {
	z[3], z[2], z[1], z[0] = 0, 0, 0, 1
	return z
}

// SetFromDecimal sets z from a decimal string and returns an error if invalid.
// Accepts an optional leading "+" sign but rejects underscores and negative values.
// Returns ErrBig256Range if the number exceeds 256 bits.
func (z *Uint) SetFromDecimal(s string) (err error) {
	sLen := len(s)
	// Remove max one leading +
	if sLen > 0 && s[0] == '+' {
		s = s[1:]
		sLen--
	}
	// Remove any number of leading zeroes
	if sLen > 0 && s[0] == '0' {
		var i int
		var c rune
		for i, c = range s {
			if c != '0' {
				break
			}
		}
		s = s[i:]
		sLen = len(s)
	}

	maxLen := len(MAX_UINT256)
	if sLen < maxLen {
		return z.fromDecimal(s)
	}
	if sLen == maxLen {
		if s > MAX_UINT256 {
			return ErrBig256Range
		}
		return z.fromDecimal(s)
	}
	return ErrBig256Range
}

// FromDecimal creates a new Uint from a decimal string.
// Returns an error if the number exceeds 256 bits or is invalid.
func FromDecimal(decimal string) (*Uint, error) {
	var z Uint
	if err := z.SetFromDecimal(decimal); err != nil {
		return nil, err
	}
	return &z, nil
}

// MustFromDecimal creates a new Uint from a decimal string.
// Panics if the string is invalid or the number exceeds 256 bits.
func MustFromDecimal(decimal string) *Uint {
	var z Uint
	if err := z.SetFromDecimal(decimal); err != nil {
		panic(err)
	}
	return &z
}

// multipliers holds the values that are needed for fromDecimal
var multipliers = [5]Uint{
	{0, 0, 0, 0},                                    // 1 (no multiplication needed in the first round)
	{10000000000000000000, 0, 0, 0},                 // 10 ^ 19
	{687399551400673280, 5421010862427522170, 0, 0}, // 10 ^ 38
	{5332261958806667264, 17004971331911604867, 2938735877055718769, 0}, // 10 ^ 57
	{0, 8607968719199866880, 532749306367912313, 1593091911132452277},   // 10 ^ 76
}

// fromDecimal parses a decimal string by processing it in 19-character chunks.
// Each chunk is multiplied by the appropriate power of 10 and accumulated.
func (z *Uint) fromDecimal(bs string) error {
	// first clear the input
	z.Clear()
	// the maximum value of uint64 is 18446744073709551615, which is 20 characters
	// one less means that a string of 19 9's is always within the uint64 limit
	var (
		num       uint64
		err       error
		remaining = len(bs)
	)
	if remaining == 0 {
		return errors.New("EOF")
	}

	// We proceed in steps of 19 characters (nibbles), from least significant to most significant.
	// This means that the first (up to) 19 characters do not need to be multiplied.
	// In the second iteration, our slice of 19 characters needs to be multiplied
	// by a factor of 10^19. Et cetera.
	for i := range multipliers {
		if remaining <= 0 {
			return nil // Done
		}
		if remaining > 19 {
			num, err = strconv.ParseUint(bs[remaining-19:remaining], 10, 64)
		} else {
			// Final round
			num, err = strconv.ParseUint(bs, 10, 64)
		}
		if err != nil {
			return err
		}
		// add that number to our running total
		if i == 0 {
			z.SetUint64(num)
		} else {
			base := &Uint{uint64(num), 0, 0, 0}
			// Check for overflow in multiplication
			base, overflow := base.MulOverflow(base, &multipliers[i])
			if overflow {
				return ErrBig256Range
			}
			// Check for overflow in addition
			base, overflow = base.AddOverflow(base, z)
			if overflow {
				return ErrBig256Range
			}
			z.Set(base)
		}
		// Chop off another 19 characters
		if remaining > 19 {
			bs = bs[0 : remaining-19]
		}
		remaining -= 19
	}
	return nil
}

// Byte returns the value of the byte at position n as a Uint.
// Position n is counted from the right (0 = least significant byte).
// Returns 0 if n >= 32.
func (z *Uint) Byte(n *Uint) *Uint {
	// in z, z[0] is the least significant
	if number, overflow := n.Uint64WithOverflow(); !overflow {
		if number < 32 {
			number := z[4-1-number/8]
			offset := (n[0] & 0x7) << 3 // 8*(n.d % 8)
			z[0] = (number & (0xff00000000000000 >> offset)) >> (56 - offset)
			z[3], z[2], z[1] = 0, 0, 0
			return z
		}
	}

	return z.Clear()
}

// BitLen returns the number of bits required to represent z.
// BitLen(0) returns 0.
func (z *Uint) BitLen() int {
	switch {
	case z[3] != 0:
		return 192 + bits.Len64(z[3])
	case z[2] != 0:
		return 128 + bits.Len64(z[2])
	case z[1] != 0:
		return 64 + bits.Len64(z[1])
	default:
		return bits.Len64(z[0])
	}
}

// ByteLen returns the number of bytes required to represent z.
// ByteLen(0) returns 0.
func (z *Uint) ByteLen() int {
	return (z.BitLen() + 7) / 8
}

// Clear sets z to 0 and returns z.
func (z *Uint) Clear() *Uint {
	z[3], z[2], z[1], z[0] = 0, 0, 0, 0
	return z
}

// Clone returns a new Uint with the same value as z.
func (z *Uint) Clone() *Uint {
	var x Uint
	x[0] = z[0]
	x[1] = z[1]
	x[2] = z[2]
	x[3] = z[3]

	return &x
}

package mpt

import (
	"bytes"
	"crypto/keccak256"
	"errors"

	"gno.land/p/onbloc/encoding/rlp"
)

var (
	ErrEmptyProof       = errors.New("mpt: empty proof")
	ErrInvalidRoot      = errors.New("mpt: invalid root length")
	ErrUnexpectedNode   = errors.New("mpt: unexpected node shape")
	ErrInvalidReference = errors.New("mpt: invalid child reference")
	ErrPathMismatch     = errors.New("mpt: path mismatch")
	ErrValueMismatch    = errors.New("mpt: value mismatch")
	ErrKeyPresent       = errors.New("mpt: key present")
	ErrKeyAbsent        = errors.New("mpt: key absent")
	ErrUnusedProof      = errors.New("mpt: unused proof nodes")
)

// EmptyRoot is keccak256(rlp("")), the root of an empty Ethereum MPT.
func EmptyRoot() [32]byte {
	return keccak256.Sum256(rlp.EncodeBytes(nil))
}

// Verify verifies an Ethereum Merkle Patricia Trie existence proof.
//
// root is the 32-byte trie root. key is expanded to nibbles and matched against
// the proof path. proof contains raw RLP-encoded nodes, ordered from root to
// leaf. value is the RLP string payload stored at the leaf or branch value slot.
func Verify(root []byte, key []byte, value []byte, proof [][]byte) error {
	result, err := walk(root, keybytesToNibbles(key), proof)
	if err != nil {
		return err
	}

	if !result.found {
		return ErrKeyAbsent
	}

	if !bytes.Equal(result.value, value) {
		return ErrValueMismatch
	}

	return nil
}

// VerifyAbsence verifies that key is absent from the trie under root.
func VerifyAbsence(root []byte, key []byte, proof [][]byte) error {
	result, err := walk(root, keybytesToNibbles(key), proof)
	if err != nil {
		return err
	}

	if result.found {
		return ErrKeyPresent
	}

	return nil
}

type walkResult struct {
	found bool
	value []byte
}

// isBytesNode reports whether an RLP value carries a byte payload (a string or
// single byte) rather than a nested list.
func isBytesNode(v rlp.Value) bool {
	return v.Kind == rlp.KindString || v.Kind == rlp.KindByte
}

func walk(root []byte, path []byte, proof [][]byte) (walkResult, error) {
	if len(root) != keccak256.Size {
		return walkResult{}, ErrInvalidRoot
	}

	if len(proof) == 0 {
		emptyRoot := EmptyRoot()
		if bytes.Equal(root, emptyRoot[:]) {
			return walkResult{found: false}, nil
		}

		return walkResult{}, ErrEmptyProof
	}

	if err := matchHash(root, proof[0]); err != nil {
		return walkResult{}, err
	}

	proofIndex := 0
	node := proof[0]
	pos := 0

	for {
		v, err := rlp.DecodeValue(node)
		if err != nil {
			return walkResult{}, err
		}

		if v.Kind != rlp.KindList {
			return walkResult{}, ErrUnexpectedNode
		}

		switch len(v.List) {
		case 17:
			if pos == len(path) {
				value := v.List[16]
				if !isBytesNode(value) {
					return walkResult{}, ErrUnexpectedNode
				}

				if len(value.Bytes) == 0 {
					return finishWalk(walkResult{found: false}, proofIndex, proof)
				}

				return finishWalk(walkResult{found: true, value: value.Bytes}, proofIndex, proof)
			}

			child := v.List[path[pos]]
			if !isBytesNode(child) {
				return walkResult{}, ErrUnexpectedNode
			}

			if len(child.Bytes) == 0 {
				return finishWalk(walkResult{found: false}, proofIndex, proof)
			}

			next, nextIndex, err := resolveReference(child.Bytes, proof, proofIndex)
			if err != nil {
				return walkResult{}, err
			}

			proofIndex = nextIndex
			node = next
			pos++

		case 2:
			if !isBytesNode(v.List[0]) {
				return walkResult{}, ErrUnexpectedNode
			}

			leaf, partial, err := compactDecode(v.List[0].Bytes)
			if err != nil {
				return walkResult{}, err
			}

			if !hasPrefix(path[pos:], partial) {
				return finishWalk(walkResult{found: false}, proofIndex, proof)
			}

			pos += len(partial)

			if leaf {
				if pos != len(path) {
					return finishWalk(walkResult{found: false}, proofIndex, proof)
				}

				value := v.List[1]
				if !isBytesNode(value) {
					return walkResult{}, ErrUnexpectedNode
				}

				return finishWalk(walkResult{found: true, value: value.Bytes}, proofIndex, proof)
			}

			child := v.List[1]
			if !isBytesNode(child) {
				return walkResult{}, ErrUnexpectedNode
			}

			next, nextIndex, err := resolveReference(child.Bytes, proof, proofIndex)
			if err != nil {
				return walkResult{}, err
			}

			proofIndex = nextIndex
			node = next

		default:
			return walkResult{}, ErrUnexpectedNode
		}
	}
}

func finishWalk(result walkResult, proofIndex int, proof [][]byte) (walkResult, error) {
	if proofIndex != len(proof)-1 {
		return walkResult{}, ErrUnusedProof
	}

	return result, nil
}

func resolveReference(ref []byte, proof [][]byte, proofIndex int) ([]byte, int, error) {
	if len(ref) == 0 {
		return nil, proofIndex, ErrInvalidReference
	}

	if len(ref) < keccak256.Size {
		return ref, proofIndex, nil
	}

	if len(ref) != keccak256.Size {
		return nil, proofIndex, ErrInvalidReference
	}

	nextIndex := proofIndex + 1
	if nextIndex >= len(proof) {
		return nil, proofIndex, ErrEmptyProof
	}

	if err := matchHash(ref, proof[nextIndex]); err != nil {
		return nil, proofIndex, err
	}

	return proof[nextIndex], nextIndex, nil
}

func matchHash(expected []byte, encodedNode []byte) error {
	h := keccak256.Sum256(encodedNode)
	if !bytes.Equal(expected, h[:]) {
		return ErrInvalidReference
	}

	return nil
}

func keybytesToNibbles(key []byte) []byte {
	out := make([]byte, 0, len(key)*2)
	for _, b := range key {
		out = append(out, b>>4, b&0x0f)
	}

	return out
}

func compactDecode(encoded []byte) (bool, []byte, error) {
	if len(encoded) == 0 {
		return false, nil, ErrPathMismatch
	}

	flag := encoded[0] >> 4
	if flag > 3 {
		return false, nil, ErrPathMismatch
	}

	leaf := (flag & 2) != 0
	odd := (flag & 1) != 0

	out := make([]byte, 0, len(encoded)*2)
	if odd {
		out = append(out, encoded[0]&0x0f)
	} else if encoded[0]&0x0f != 0 {
		return false, nil, ErrPathMismatch
	}

	for i := 1; i < len(encoded); i++ {
		out = append(out, encoded[i]>>4, encoded[i]&0x0f)
	}
	// extensions nodes must contain at least one path nibble.
	// empty extension paths are non-canonical because they admit
	// alternative proof encoding.
	if !leaf && len(out) == 0 {
		return false, nil, ErrPathMismatch
	}

	return leaf, out, nil
}

func hasPrefix(path []byte, prefix []byte) bool {
	if len(prefix) > len(path) {
		return false
	}

	for i := range prefix {
		if path[i] != prefix[i] {
			return false
		}
	}

	return true
}

package abi

import (
	"encoding/binary"

	u256 "gno.land/p/onbloc/math/uint256"
)

// Decode ABI-decodes data according to schema using Solidity's params tuple form.
func Decode(schema Schema, data []byte) ([]any, error) {
	if len(data)%wordSize != 0 {
		return nil, ErrInvalidData
	}

	d := decoder{data: data, maxDepth: maxDecodeDepth}

	return d.tupleAt(schema.Fields, 0, len(data), 0)
}

type decoder struct {
	data     []byte
	maxDepth int
}

func (d *decoder) tupleAt(fields []Field, start, end, depth int) ([]any, error) {
	depth++
	if depth > d.maxDepth {
		return nil, ErrDepthLimit
	}

	if start < 0 || end < start || end > len(d.data) {
		return nil, ErrInvalidData
	}

	out := make([]any, len(fields))
	cursor := start

	for i, field := range fields {
		dyn := isDynamic(field)
		size := wordSize

		if !dyn {
			s, err := staticHeadSize(field)
			if err != nil {
				return nil, err
			}

			size = s
		}

		// prevent `cursor+size` overflow
		if size < 0 || cursor > end || size > end-cursor {
			return nil, ErrInvalidData
		}

		if dyn {
			offset, err := decodeWordUint64(d.data[cursor : cursor+wordSize])
			if err != nil {
				return nil, err
			}

			if offset > uint64(end-start) || offset%wordSize != 0 {
				return nil, ErrInvalidData
			}

			pos := start + int(offset)

			out[i], err = d.valueAt(field, pos, end, depth)
			if err != nil {
				return nil, err
			}

			cursor += wordSize
		} else {
			v, err := d.staticValue(field, cursor, end, depth)
			if err != nil {
				return nil, err
			}

			out[i] = v
			cursor += size
		}
	}

	return out, nil
}

func (d *decoder) valueAt(field Field, pos, end, depth int) (any, error) {
	switch field.Type {
	case TypeBytes:
		return d.bytesAt(pos, end)
	case TypeString:
		bz, err := d.bytesAt(pos, end)
		if err != nil {
			return nil, err
		}

		return string(bz), nil
	case TypeStruct:
		if field.Sub == nil {
			return nil, ErrInvalidSchema
		}

		return d.tupleAt(field.Sub.Fields, pos, end, depth)
	case TypeArray:
		if field.Elem == nil {
			return nil, ErrInvalidSchema
		}

		return d.arrayAt(*field.Elem, pos, end, depth)
	default:
		return d.staticValue(field, pos, end, depth)
	}
}

func (d *decoder) staticValue(field Field, pos, end, depth int) (any, error) {
	if pos+wordSize > end {
		return nil, ErrInvalidData
	}

	switch field.Type {
	case TypeUint8:
		v, err := decodeWordUint64(d.data[pos : pos+wordSize])
		if err != nil || v > 255 {
			return nil, ErrInvalidData
		}

		return uint8(v), nil
	case TypeUint32:
		v, err := decodeWordUint64(d.data[pos : pos+wordSize])
		if err != nil || v > 0xFFFFFFFF {
			return nil, ErrInvalidData
		}

		return uint32(v), nil
	case TypeUint64:
		v, err := decodeWordUint64(d.data[pos : pos+wordSize])
		if err != nil {
			return nil, err
		}

		return v, nil
	case TypeUint256:
		var out u256.Uint
		out.SetBytes32(d.data[pos : pos+wordSize])

		return &out, nil
	case TypeBytes32:
		var out [32]byte
		copy(out[:], d.data[pos:pos+wordSize])

		return out, nil
	case TypeBool:
		v, err := decodeWordUint64(d.data[pos : pos+wordSize])
		if err != nil || v > 1 {
			return nil, ErrInvalidData
		}

		return v == 1, nil
	case TypeAddress:
		for i := pos; i < pos+12; i++ {
			if d.data[i] != 0 {
				return nil, ErrInvalidData
			}
		}

		out := make([]byte, 20)
		copy(out, d.data[pos+12:pos+wordSize])

		return out, nil
	case TypeStruct:
		if field.Sub == nil {
			return nil, ErrInvalidSchema
		}

		return d.tupleAt(field.Sub.Fields, pos, end, depth)
	default:
		return nil, ErrUnsupportedType
	}
}

func (d *decoder) arrayAt(elem Field, pos, end, depth int) ([]any, error) {
	depth++
	if depth > d.maxDepth {
		return nil, ErrDepthLimit
	}

	if pos > end || wordSize > end-pos {
		return nil, ErrInvalidData
	}

	length, err := decodeWordUint64(d.data[pos : pos+wordSize])
	if err != nil {
		return nil, err
	}

	if length > uint64((end-pos)/wordSize) {
		return nil, ErrInvalidData
	}

	n := int(length)
	out := make([]any, n)

	headStart := pos + wordSize
	if isDynamic(elem) {
		if n > (end-headStart)/wordSize {
			return nil, ErrInvalidData
		}

		for i := 0; i < n; i++ {
			offset, err := decodeWordUint64(d.data[headStart+i*wordSize : headStart+(i+1)*wordSize])
			if err != nil {
				return nil, err
			}

			if offset > uint64(end-headStart) || offset%wordSize != 0 {
				return nil, ErrInvalidData
			}

			elemPos := headStart + int(offset)

			out[i], err = d.valueAt(elem, elemPos, end, depth)
			if err != nil {
				return nil, err
			}
		}

		return out, nil
	}

	elemSize, err := staticHeadSize(elem)
	if err != nil {
		return nil, err
	}

	if elemSize <= 0 || n > (end-headStart)/elemSize {
		return nil, ErrInvalidData
	}

	for i := 0; i < n; i++ {
		out[i], err = d.staticValue(elem, headStart+i*elemSize, end, depth)
		if err != nil {
			return nil, err
		}
	}

	return out, nil
}

func (d *decoder) bytesAt(pos, end int) ([]byte, error) {
	if pos+wordSize > end {
		return nil, ErrInvalidData
	}

	length, err := decodeWordUint64(d.data[pos : pos+wordSize])
	if err != nil {
		return nil, err
	}

	start := pos + wordSize
	remaining := uint64(end - start)

	padded := roundUp32(length)
	if padded < length || length > remaining || padded > remaining {
		return nil, ErrInvalidData
	}

	out := make([]byte, int(length))
	copy(out, d.data[start:start+int(length)])

	return out, nil
}

func decodeWordUint64(word []byte) (uint64, error) {
	if len(word) != wordSize {
		return 0, ErrInvalidData
	}

	for i := 0; i < 24; i++ {
		if word[i] != 0 {
			return 0, ErrInvalidData
		}
	}

	return binary.BigEndian.Uint64(word[24:32]), nil
}

func roundUp32(v uint64) uint64 {
	if v%wordSize == 0 {
		return v
	}

	return v + wordSize - v%wordSize
}

package abi

import (
	"encoding/binary"

	u256 "gno.land/p/onbloc/math/uint256"
)

// Encode ABI-encodes values according to schema using Solidity's params tuple form.
func Encode(schema Schema, values []any) ([]byte, error) {
	return encodeTuple(schema.Fields, values)
}

func encodeTuple(fields []Field, values []any) ([]byte, error) {
	if len(fields) != len(values) {
		return nil, ErrInvalidValue
	}

	dyn := make([]bool, len(fields))
	headLen := 0

	for i, field := range fields {
		dyn[i] = isDynamic(field)
		if dyn[i] {
			headLen += wordSize
			continue
		}

		size, err := staticHeadSize(field)
		if err != nil {
			return nil, err
		}

		headLen += size
	}

	head := make([]byte, 0, headLen)

	var tail []byte

	for i, field := range fields {
		encoded, err := encodeValue(field, values[i])
		if err != nil {
			return nil, err
		}

		if dyn[i] {
			head = append(head, encodeUint64Word(uint64(headLen+len(tail)))...)
			tail = append(tail, encoded...)
		} else {
			head = append(head, encoded...)
		}
	}

	return append(head, tail...), nil
}

func encodeValue(field Field, value any) ([]byte, error) {
	switch field.Type {
	case TypeUint8:
		v, ok := value.(uint8)
		if !ok {
			return nil, ErrInvalidValue
		}

		return encodeUint64Word(uint64(v)), nil
	case TypeUint32:
		v, ok := value.(uint32)
		if !ok {
			return nil, ErrInvalidValue
		}

		return encodeUint64Word(uint64(v)), nil
	case TypeUint64:
		v, ok := value.(uint64)
		if !ok {
			return nil, ErrInvalidValue
		}

		return encodeUint64Word(v), nil
	case TypeUint256:
		v, ok := value.(*u256.Uint)
		if !ok || v == nil {
			return nil, ErrInvalidValue
		}

		return encodeUint256Word(v), nil
	case TypeBytes32:
		v, ok := value.([32]byte)
		if !ok {
			return nil, ErrInvalidValue
		}

		out := make([]byte, wordSize)
		copy(out, v[:])

		return out, nil
	case TypeBytes:
		v, ok := value.([]byte)
		if !ok {
			return nil, ErrInvalidValue
		}

		return encodeBytes(v), nil
	case TypeString:
		v, ok := value.(string)
		if !ok {
			return nil, ErrInvalidValue
		}

		return encodeBytes([]byte(v)), nil
	case TypeBool:
		v, ok := value.(bool)
		if !ok {
			return nil, ErrInvalidValue
		}

		if v {
			return encodeUint64Word(1), nil
		}

		return encodeUint64Word(0), nil
	case TypeAddress:
		v, ok := value.([]byte)
		if !ok || len(v) != 20 {
			return nil, ErrInvalidValue
		}

		out := make([]byte, wordSize)
		copy(out[12:], v)

		return out, nil
	case TypeStruct:
		if field.Sub == nil {
			return nil, ErrInvalidSchema
		}

		v, ok := value.([]any)
		if !ok {
			return nil, ErrInvalidValue
		}

		return encodeTuple(field.Sub.Fields, v)
	case TypeArray:
		if field.Elem == nil {
			return nil, ErrInvalidSchema
		}

		v, ok := value.([]any)
		if !ok {
			return nil, ErrInvalidValue
		}

		return encodeArray(*field.Elem, v)
	default:
		return nil, ErrUnsupportedType
	}
}

func encodeArray(elem Field, values []any) ([]byte, error) {
	out := encodeUint64Word(uint64(len(values)))
	if len(values) == 0 {
		return out, nil
	}

	if isDynamic(elem) {
		headLen := len(values) * wordSize
		head := make([]byte, 0, headLen)

		var tail []byte

		for _, value := range values {
			encoded, err := encodeValue(elem, value)
			if err != nil {
				return nil, err
			}

			head = append(head, encodeUint64Word(uint64(headLen+len(tail)))...)
			tail = append(tail, encoded...)
		}

		out = append(out, head...)

		return append(out, tail...), nil
	}

	for _, value := range values {
		encoded, err := encodeValue(elem, value)
		if err != nil {
			return nil, err
		}

		out = append(out, encoded...)
	}

	return out, nil
}

func encodeBytes(v []byte) []byte {
	pad := (wordSize - len(v)%wordSize) % wordSize
	out := make([]byte, 0, wordSize+len(v)+pad)
	out = append(out, encodeUint64Word(uint64(len(v)))...)

	out = append(out, v...)
	if pad > 0 {
		out = append(out, make([]byte, pad)...)
	}

	return out
}

func encodeUint64Word(v uint64) []byte {
	out := make([]byte, wordSize)
	binary.BigEndian.PutUint64(out[24:], v)

	return out
}

// NOTE: depends on gnoswap/uint256's internal [4]uint64 layout (mirror of
// SetBytes32). Replace with the upstream Bytes32() method once it exists.
// Same workaround lives in ibc/union/zkgm/salt.gno; consolidate when fixed.
func encodeUint256Word(v *u256.Uint) []byte {
	out := make([]byte, wordSize)
	binary.BigEndian.PutUint64(out[0:8], v[3])
	binary.BigEndian.PutUint64(out[8:16], v[2])
	binary.BigEndian.PutUint64(out[16:24], v[1])
	binary.BigEndian.PutUint64(out[24:32], v[0])

	return out
}

func isDynamic(field Field) bool {
	switch field.Type {
	case TypeBytes, TypeString, TypeArray:
		return true
	case TypeStruct:
		if field.Sub == nil {
			return true
		}

		for _, sub := range field.Sub.Fields {
			if isDynamic(sub) {
				return true
			}
		}

		return false
	default:
		return false
	}
}

func staticHeadSize(field Field) (int, error) {
	if isDynamic(field) {
		return wordSize, nil
	}

	if field.Type == TypeStruct {
		if field.Sub == nil {
			return 0, ErrInvalidSchema
		}

		size := 0

		for _, sub := range field.Sub.Fields {
			subSize, err := staticHeadSize(sub)
			if err != nil {
				return 0, err
			}

			size += subSize
		}

		return size, nil
	}

	return wordSize, nil
}

package abi

import "errors"

// Type identifies a Solidity ABI field kind supported by this package.
type Type int

const (
	TypeUint8 Type = iota
	TypeUint32
	TypeUint64
	TypeUint256
	TypeBytes32
	TypeBytes
	TypeString
	TypeBool
	TypeAddress
	TypeStruct
	TypeArray
)

var (
	ErrUnsupportedType = errors.New("abi: unsupported type")
	ErrInvalidSchema   = errors.New("abi: invalid schema")
	ErrInvalidValue    = errors.New("abi: invalid value")
	ErrInvalidData     = errors.New("abi: invalid data")
	ErrDepthLimit      = errors.New("abi: depth limit exceeded")
)

// Field describes one ABI tuple field.
type Field struct {
	Type Type
	Sub  *Schema
	Elem *Field
}

// Schema describes a Solidity ABI tuple.
type Schema struct {
	Fields []Field
}

const (
	wordSize        = 32
	maxDecodeDepth  = 256
)

package tokenbucket

import (
	"errors"

	u256 "gno.land/p/onbloc/math/uint256"
)

var (
	ErrZeroCapacity         = errors.New("tokenbucket: capacity must not be zero")
	ErrZeroRefillRate       = errors.New("tokenbucket: refill rate must not be zero")
	ErrRateLimitExceeded    = errors.New("tokenbucket: rate limit exceeded")
	ErrTokenBucketUnderflow = errors.New("tokenbucket: token bucket underflow")
)

type TokenBucket struct {
	Capacity   *u256.Uint
	Available  *u256.Uint
	RefillRate *u256.Uint
	LastRefill *u256.Uint
}

func New(capacity *u256.Uint, refillRate *u256.Uint, now *u256.Uint) (*TokenBucket, error) {
	if capacity.IsZero() {
		return nil, ErrZeroCapacity
	}

	if refillRate.IsZero() {
		return nil, ErrZeroRefillRate
	}

	return &TokenBucket{
		Capacity:   capacity.Clone(),
		Available:  capacity.Clone(),
		RefillRate: refillRate.Clone(),
		LastRefill: now.Clone(),
	}, nil
}

func (tb *TokenBucket) Refill(now *u256.Uint) {
	if now.Lte(tb.LastRefill) {
		return
	}

	if tb.Available.Gte(tb.Capacity) {
		tb.LastRefill.Set(now)
		return
	}

	elapsed, underflow := u256.Zero().SubOverflow(now, tb.LastRefill)
	if underflow {
		panic(ErrTokenBucketUnderflow)
	}

	toRefill := saturatingMul(tb.RefillRate, elapsed)
	tb.Available = min(tb.Capacity, saturatingAdd(tb.Available, toRefill))
	tb.LastRefill.Set(now)
}

func (tb *TokenBucket) RateLimit(amount *u256.Uint, now *u256.Uint) error {
	if amount.IsZero() {
		return nil
	}

	tb.Refill(now)

	if tb.Available.Lt(amount) {
		return ErrRateLimitExceeded
	}

	tb.Available = u256.Zero().Sub(tb.Available, amount)

	return nil
}

func (tb *TokenBucket) Update(capacity *u256.Uint, refillRate *u256.Uint, reset bool) error {
	if capacity.IsZero() {
		return ErrZeroCapacity
	}

	if refillRate.IsZero() {
		return ErrZeroRefillRate
	}

	tb.Capacity = capacity.Clone()
	tb.RefillRate = refillRate.Clone()

	// Mirror union's token_bucket update (token_bucket.rs L84-88): only reset
	// available on first init or explicit reset. Do NOT clamp available down when
	// capacity shrinks — union lets a now-excess available drain naturally.
	if tb.LastRefill.IsZero() || reset {
		tb.Available = tb.Capacity.Clone()
	}

	return nil
}

func saturatingAdd(x *u256.Uint, y *u256.Uint) *u256.Uint {
	z, overflow := u256.Zero().AddOverflow(x, y)
	if overflow {
		return u256.Zero().SetAllOne()
	}

	return z
}

func saturatingMul(x *u256.Uint, y *u256.Uint) *u256.Uint {
	z, overflow := u256.Zero().MulOverflow(x, y)
	if overflow {
		return u256.Zero().SetAllOne()
	}

	return z
}

func min(x *u256.Uint, y *u256.Uint) *u256.Uint {
	if x.Lte(y) {
		return x.Clone()
	}

	return y.Clone()
}

package storage

import (
	"encoding/binary"
	"errors"
)

var (
	ErrInvalidProofBytes  = errors.New("storage: invalid proof bytes")
	ErrTrailingProofBytes = errors.New("storage: trailing proof bytes")
)

// DecodeProof decodes Union's ethereum_light_client_types::StorageProof
// bincode wire form into the normalized Proof shape used by this package.
//
// Wire layout with fixed-int/little-endian bincode:
//   - key: U256 as 32 little-endian bytes
//   - value: U256 as 32 little-endian bytes
//   - proof: Vec<Bytes> as u64 length followed by repeated byte vectors
func DecodeProof(buf []byte) (Proof, error) {
	d := proofDecoder{buf: buf}

	key, err := d.readU256()
	if err != nil {
		return Proof{}, err
	}

	value, err := d.readU256()
	if err != nil {
		return Proof{}, err
	}

	count, err := d.readUint64()
	if err != nil {
		return Proof{}, err
	}

	if count > uint64(len(buf)) {
		return Proof{}, ErrInvalidProofBytes
	}

	proof := make([][]byte, int(count))
	for i := 0; i < int(count); i++ {
		proof[i], err = d.readBytes()
		if err != nil {
			return Proof{}, err
		}
	}

	if d.pos != len(buf) {
		return Proof{}, ErrTrailingProofBytes
	}

	return Proof{Key: key, Value: value, Proof: proof}, nil
}

func EncodeProof(proof Proof) []byte {
	var out []byte

	out = append(out, reverse32(proof.Key)...)
	out = append(out, reverse32(proof.Value)...)
	out = appendUint64LE(out, uint64(len(proof.Proof)))

	for _, node := range proof.Proof {
		out = appendUint64LE(out, uint64(len(node)))
		out = append(out, node...)
	}

	return out
}

type proofDecoder struct {
	buf []byte
	pos int
}

func (d *proofDecoder) readU256() ([]byte, error) {
	if d.pos+32 > len(d.buf) {
		return nil, ErrInvalidProofBytes
	}

	le := d.buf[d.pos : d.pos+32]
	d.pos += 32

	out := make([]byte, 32)
	for i := 0; i < 32; i++ {
		out[i] = le[31-i]
	}

	return out, nil
}

func (d *proofDecoder) readBytes() ([]byte, error) {
	n, err := d.readUint64()
	if err != nil {
		return nil, err
	}

	if n > uint64(len(d.buf)-d.pos) {
		return nil, ErrInvalidProofBytes
	}

	out := make([]byte, int(n))
	copy(out, d.buf[d.pos:d.pos+int(n)])
	d.pos += int(n)

	return out, nil
}

func (d *proofDecoder) readUint64() (uint64, error) {
	if d.pos+8 > len(d.buf) {
		return 0, ErrInvalidProofBytes
	}

	v := binary.LittleEndian.Uint64(d.buf[d.pos : d.pos+8])
	d.pos += 8

	return v, nil
}

func appendUint64LE(out []byte, v uint64) []byte {
	var word [8]byte
	binary.LittleEndian.PutUint64(word[:], v)

	return append(out, word[:]...)
}

func reverse32(b []byte) []byte {
	out := make([]byte, 32)

	n := len(b)
	if n > 32 {
		n = 32
	}

	for i := 0; i < n; i++ {
		out[i] = b[len(b)-1-i]
	}

	return out
}

package storage

import (
	"bytes"
	"crypto/keccak256"
	"encoding/binary"
	"errors"

	"gno.land/p/onbloc/encoding/rlp"
	"gno.land/p/onbloc/verifier/evm/mpt"
)

var (
	ErrInvalidRootLength  = errors.New("storage: root must be 32 bytes")
	ErrInvalidKeyLength   = errors.New("storage: key must be 32 bytes")
	ErrInvalidPathLength  = errors.New("storage: path must be 32 bytes")
	ErrInvalidValueLength = errors.New("storage: value must be 32 bytes")
	ErrValueMismatch      = errors.New("storage: value mismatch")
)

// Proof is the storage proof shape returned by eth_getProof for one slot,
// normalized to bytes. Key and Value are 32-byte EVM words. Proof contains the
// raw RLP-encoded trie nodes from root to leaf.
//
// It is also the normalized form of Union's
// ethereum_light_client_types::StorageProof wire type:
// https://github.com/unionlabs/union/blob/main/lib/ethereum-light-client-types/src/storage_proof.rs
type Proof struct {
	Key   []byte
	Value []byte
	Proof [][]byte
}

// VerifyProof verifies that proof.Key stores proof.Value under storageRoot.
// Ethereum storage tries are keyed by keccak256(slot), and the leaf payload is
// the RLP encoding of the storage value with leading zero bytes removed.
func VerifyProof(storageRoot []byte, proof Proof) error {
	err := validateWord(storageRoot, ErrInvalidRootLength)
	if err != nil {
		return err
	}

	err = validateWord(proof.Key, ErrInvalidKeyLength)
	if err != nil {
		return err
	}

	err = validateWord(proof.Value, ErrInvalidValueLength)
	if err != nil {
		return err
	}

	path := keccak256.Sum256(proof.Key)

	return mpt.Verify(storageRoot, path[:], encodeStorageValue(proof.Value), proof.Proof)
}

// VerifyAbsence verifies that proof.Key is absent under storageRoot. The Value
// field is intentionally ignored for absence proofs because eth_getProof returns
// zero for missing slots.
func VerifyAbsence(storageRoot []byte, proof Proof) error {
	err := validateWord(storageRoot, ErrInvalidRootLength)
	if err != nil {
		return err
	}

	err = validateWord(proof.Key, ErrInvalidKeyLength)
	if err != nil {
		return err
	}

	path := keccak256.Sum256(proof.Key)

	return mpt.VerifyAbsence(storageRoot, path[:], proof.Proof)
}

// CheckValue verifies only the value reported by the proof object. This is
// useful when a caller receives an expected 32-byte commitment separately.
func CheckValue(proof Proof, expected []byte) error {
	err := validateWord(proof.Value, ErrInvalidValueLength)
	if err != nil {
		return err
	}

	err = validateWord(expected, ErrInvalidValueLength)
	if err != nil {
		return err
	}

	if !bytes.Equal(proof.Value, expected) {
		return ErrValueMismatch
	}

	return nil
}

// StoragePath returns the MPT path used for an EVM storage slot.
func StoragePath(slot []byte) ([32]byte, error) {
	err := validateWord(slot, ErrInvalidKeyLength)
	if err != nil {
		return [32]byte{}, err
	}

	return keccak256.Sum256(slot), nil
}

// IBCCommitmentKey mirrors Union's ethereum::ibc_commitment_key for
// mapping(bytes32 => bytes32) commitments at slot 0.
//
// Union reference:
// https://github.com/unionlabs/union/blob/main/lib/unionlabs/src/ethereum.rs
func IBCCommitmentKey(path []byte) ([32]byte, error) {
	err := validateWord(path, ErrInvalidPathLength)
	if err != nil {
		return [32]byte{}, err
	}

	var input [64]byte

	copy(input[0:32], path)

	return keccak256.Sum256(input[:]), nil
}

// EncodeStorageValue returns the leaf payload expected by the storage trie.
func EncodeStorageValue(word []byte) ([]byte, error) {
	err := validateWord(word, ErrInvalidValueLength)
	if err != nil {
		return nil, err
	}

	return encodeStorageValue(word), nil
}

func validateWord(word []byte, err error) error {
	if len(word) != 32 {
		return err
	}

	return nil
}

func encodeStorageValue(word []byte) []byte {
	return rlp.EncodeBytes(trimLeadingZeroes(word))
}

func trimLeadingZeroes(word []byte) []byte {
	i := 0

	for i < len(word) && word[i] == 0 {
		i++
	}

	return word[i:]
}

func WordFromUint64(v uint64) []byte {
	out := make([]byte, 32)
	binary.BigEndian.PutUint64(out[24:], v)

	return out
}

package types

import "encoding/binary"

// wrapABIEncode wraps an already-encoded dynamic ABI payload with the
// 32-byte offset header that Solidity prepends when a single dynamic value is
// returned at the top level.
func wrapABIEncode(encoded []byte) []byte {
	out := make([]byte, 0, 32+len(encoded))
	out = append(out, u64ToH256(32)...)

	return append(out, encoded...)
}

func encodeABIPacketArray(packets []Packet) ([]byte, error) {
	out := make([]byte, 0)
	out = append(out, u64ToH256(uint64(len(packets)))...)

	headLen := len(packets) * 32
	tail := make([]byte, 0)

	for _, packet := range packets {
		encoded, err := packet.EncodeABI()
		if err != nil {
			return nil, err
		}

		out = append(out, u64ToH256(uint64(headLen+len(tail)))...)
		tail = append(tail, encoded...)
	}

	return append(out, tail...), nil
}

func encodeABIBytesArray(items [][]byte) []byte {
	out := make([]byte, 0)
	out = append(out, u64ToH256(uint64(len(items)))...)

	headLen := len(items) * 32
	tail := make([]byte, 0)

	for _, item := range items {
		encoded := encodeABIBytes(item)

		out = append(out, u64ToH256(uint64(headLen+len(tail)))...)
		tail = append(tail, encoded...)
	}

	return append(out, tail...)
}

// encodeABIBytes encodes bz as a Solidity `bytes` value: a 32-byte length word
// followed by the data right-padded to a 32-byte boundary.
func encodeABIBytes(bz []byte) []byte {
	pad := (32 - len(bz)%32) % 32
	out := make([]byte, 0, 32+len(bz)+pad)
	out = append(out, u64ToH256(uint64(len(bz)))...)

	out = append(out, bz...)
	if pad > 0 {
		out = append(out, make([]byte, pad)...)
	}

	return out
}

// u32ToH256 left-pads a uint32 into a 32-byte big-endian word.
func u32ToH256(n uint32) []byte {
	bz := [32]byte{}
	binary.BigEndian.PutUint32(bz[28:], n)

	return bz[:]
}

// u64ToH256 left-pads a uint64 into a 32-byte big-endian word.
func u64ToH256(n uint64) []byte {
	bz := [32]byte{}
	binary.BigEndian.PutUint64(bz[24:], n)

	return bz[:]
}

package types

import (
	"strconv"

	"gno.land/p/onbloc/encoding/abi"
)

type ChannelId uint32

func (id ChannelId) String() string {
	return strconv.FormatUint(uint64(id), 10)
}

type ChannelState uint8

const (
	ChannelStateUnknown ChannelState = 0
	ChannelStateInit    ChannelState = 1
	ChannelStateTryOpen ChannelState = 2
	ChannelStateOpen    ChannelState = 3
	ChannelStateClosed  ChannelState = 4
)

type Channel struct {
	State                 ChannelState
	ConnectionId          ConnectionId
	CounterpartyChannelId ChannelId
	CounterpartyPortId    Bytes
	Version               string
}

func (c Channel) EncodeABI() ([]byte, error) {
	schema := abi.Schema{Fields: []abi.Field{
		{Type: abi.TypeUint8},
		{Type: abi.TypeUint32},
		{Type: abi.TypeUint32},
		{Type: abi.TypeBytes},
		{Type: abi.TypeString},
	}}

	bz, err := abi.Encode(schema, []any{
		uint8(c.State),
		uint32(c.ConnectionId),
		uint32(c.CounterpartyChannelId),
		c.CounterpartyPortId.Bytes(),
		c.Version,
	})
	if err != nil {
		return nil, err
	}

	return wrapABIEncode(bz), nil
}

func NewChannel(
	state ChannelState,
	connectionId ConnectionId,
	counterpartyChannelId ChannelId,
	counterpartyPortId Bytes,
	version string,
) Channel {
	return Channel{
		State:                 state,
		ConnectionId:          connectionId,
		CounterpartyChannelId: counterpartyChannelId,
		CounterpartyPortId:    counterpartyPortId,
		Version:               version,
	}
}

package types

type Status uint8

const (
	StatusUnknown Status = 0
	StatusActive  Status = 1
	StatusExpired Status = 2
	StatusFrozen  Status = 3
)

// ConsensusStateUpdate carries the height-stamped consensus and client state
// bytes a light client returns after verifying a header update.
type ConsensusStateUpdate struct {
	Height              Height
	ConsensusStateBytes []byte
	ClientStateBytes    []byte
}

func NewConsensusStateUpdate(height Height, consensusStateBytes, clientStateBytes []byte) ConsensusStateUpdate {
