		ConsensusStateBytes: consensusStateBytes,
		ClientStateBytes:    clientStateBytes,
	}
}

package types

// COMMITMENT_MAGIC, COMMITMENT_MAGIC_ACK and mergeAck are defined in path.gno.

// CommitPacket returns the Union commitment hash of a single packet.
func CommitPacket(packet Packet) (H256, error) {
	return CommitPackets([]Packet{packet})
}

// CommitPackets returns the Union commitment hash of a packet batch: the
// keccak of the top-level-dynamic-wrapped ABI packet array.
func CommitPackets(packets []Packet) (H256, error) {
	encoded, err := encodeABIPacketArray(packets)
	if err != nil {
		return H256{}, err
	}

	return Keccak(wrapABIEncode(encoded)), nil
}

// MustCommit unwraps a commitment hash or panics on encoding errors.
func MustCommit(h H256, err error) H256 {
	if err != nil {
		panic(err)
	}

	return h
}

// CommitAck returns the Union commitment hash of a single acknowledgement.
func CommitAck(ack []byte) H256 {
	return CommitAcks([][]byte{ack})
}

// CommitAcks returns the Union commitment hash of an acknowledgement batch,
// with the leading byte replaced by the commitment magic.
func CommitAcks(acks [][]byte) H256 {
	return mergeAck(Keccak(wrapABIEncode(encodeABIBytesArray(acks))))
}

package types

import "gno.land/p/onbloc/encoding/abi"

type ConnectionState uint8

const (
	ConnectionStateUnknown ConnectionState = 0
	ConnectionStateInit    ConnectionState = 1
	ConnectionStateTryOpen ConnectionState = 2
	ConnectionStateOpen    ConnectionState = 3
)

type Connection struct {
	State                    ConnectionState
	ClientId                 ClientId
	CounterpartyClientId     ClientId
	CounterpartyConnectionId ConnectionId
}

func (c Connection) EncodeABI() ([]byte, error) {
	schema := abi.Schema{Fields: []abi.Field{
		{Type: abi.TypeUint8},
		{Type: abi.TypeUint32},
		{Type: abi.TypeUint32},
		{Type: abi.TypeUint32},
	}}

	bz, err := abi.Encode(schema, []any{
		uint8(c.State),
		uint32(c.ClientId),
		uint32(c.CounterpartyClientId),
		uint32(c.CounterpartyConnectionId),
	})
	if err != nil {
		return nil, err
	}

	return bz, nil
}

func NewConnection(state ConnectionState, clientId, counterpartyClientId ClientId, counterpartyConnectionId ConnectionId) Connection {
	return Connection{
		State:                    state,
		ClientId:                 clientId,
		CounterpartyClientId:     counterpartyClientId,
		CounterpartyConnectionId: counterpartyConnectionId,
	}
}

package types

import (
	"encoding/binary"
	"errors"
	"strconv"
	"strings"
)

// Height is a blockchain height, optionally prefixed with a revision number as
// per the IBC specification. A revision of zero is treated as "no revision":
// it is omitted from the string form and ignored during comparison, mirroring
// the Rust `Option<NonZeroU64>` revision semantics.
type Height struct {
	// the revision that the client is currently on
	RevisionNumber uint64
	// the height within the given revision
	RevisionHeight uint64
}

// NewHeight returns a Height with no revision.
func NewHeight(height uint64) Height {
	return Height{RevisionNumber: 0, RevisionHeight: height}
}

// NewHeightWithRevision returns a Height carrying both a revision and a height.
func NewHeightWithRevision(revision, height uint64) Height {
	return Height{RevisionNumber: revision, RevisionHeight: height}
}

// IsZero reports whether the height is the zero value (no revision, zero
// height). Union packets require a zero timeout height.
func (h Height) IsZero() bool {
	return h.RevisionNumber == 0 && h.RevisionHeight == 0
}

// HasRevision reports whether the height carries a non-zero revision number.
func (h Height) HasRevision() bool {
	return h.RevisionNumber != 0
}

// GetRevision returns the revision number, or zero when unset.
func (h Height) GetRevision() uint64 {
	return h.RevisionNumber
}

// GetHeight returns the height number.
func (h Height) GetHeight() uint64 {
	return h.RevisionHeight
}

// RevisionMatches reports whether two heights share the same revision. When
// either side has no revision the revisions are considered compatible.
func (h Height) RevisionMatches(other Height) bool {
	if h.RevisionNumber == 0 || other.RevisionNumber == 0 {
		return true
	}

	return h.RevisionNumber == other.RevisionNumber
}

// Increment returns a copy of the height advanced by one, preserving revision.
func (h Height) Increment() Height {
	return Height{RevisionNumber: h.RevisionNumber, RevisionHeight: h.RevisionHeight + 1}
}

// IncrementBy returns a copy of the height advanced by n, preserving revision.
func (h Height) IncrementBy(n uint64) Height {
	return Height{RevisionNumber: h.RevisionNumber, RevisionHeight: h.RevisionHeight + n}
}

// Cmp compares two heights, returning -1, 0, or 1. When both heights carry a
// revision, revisions are compared first and heights break the tie; otherwise
// only the height numbers are compared.
func (h Height) Cmp(other Height) int {
	if h.RevisionNumber != 0 && other.RevisionNumber != 0 {
		switch {
		case h.RevisionNumber < other.RevisionNumber:
			return -1
		case h.RevisionNumber > other.RevisionNumber:
			return 1
		}
	}

	switch {
	case h.RevisionHeight < other.RevisionHeight:
		return -1
	case h.RevisionHeight > other.RevisionHeight:
		return 1
	default:
		return 0
	}
}

// LT reports whether h is strictly less than other.
func (h Height) LT(other Height) bool { return h.Cmp(other) < 0 }

// LTE reports whether h is less than or equal to other.
func (h Height) LTE(other Height) bool { return h.Cmp(other) <= 0 }

// GT reports whether h is strictly greater than other.
func (h Height) GT(other Height) bool { return h.Cmp(other) > 0 }

// GTE reports whether h is greater than or equal to other.
func (h Height) GTE(other Height) bool { return h.Cmp(other) >= 0 }

// EQ reports whether h equals other under height comparison semantics.
func (h Height) EQ(other Height) bool { return h.Cmp(other) == 0 }

// String renders the height as "revision-height" when a revision is set, or as
// the bare height otherwise.
func (h Height) String() string {
	if h.RevisionNumber != 0 {
		return strconv.FormatUint(h.RevisionNumber, 10) + "-" + strconv.FormatUint(h.RevisionHeight, 10)
	}

	return strconv.FormatUint(h.RevisionHeight, 10)
}

// Bytes returns a 16-byte big-endian encoding of the height (revision then
// height), suitable as a BPTree key with correct lexicographic ordering when
// cast to string.
func (h Height) Bytes() []byte {
	buf := make([]byte, 16)
	binary.BigEndian.PutUint64(buf[:8], h.RevisionNumber)
	binary.BigEndian.PutUint64(buf[8:], h.RevisionHeight)

	return buf
}

// ParseHeight parses a height string of the form "revision-height" or a bare
// "height". A "revision-height" form always carries its revision, even when it
// is zero.
func ParseHeight(s string) (Height, error) {
	if s == "" {
		return Height{}, errors.New("types: invalid height string")
	}

	revStr, heightStr, found := strings.Cut(s, "-")
	if !found {
		height, err := strconv.ParseUint(s, 10, 64)
		if err != nil {
			return Height{}, err
		}

		return Height{RevisionNumber: 0, RevisionHeight: height}, nil
	}

	revision, err := strconv.ParseUint(revStr, 10, 64)
	if err != nil {
		return Height{}, err
	}

	height, err := strconv.ParseUint(heightStr, 10, 64)
	if err != nil {
		return Height{}, err
	}

	return Height{RevisionNumber: revision, RevisionHeight: height}, nil
}

package types

import "crypto/keccak256"

// Keccak hashes bz with keccak256 and returns the result as an H256.
// Exported for realm callers (core commits state roots with it).
func Keccak(bz []byte) H256 {
	sum := keccak256.Sum256(bz)

	var out H256

	for i := range out {
		out[i] = sum[i]
	}

	return out
}

package types

// ClientState is the marker interface a light client's client-state satisfies.
// Concrete client states (e.g. cometbls.ClientState) implement it so the
// lightclient.Interface can return them opaquely; callers downcast as needed.
type ClientState interface {
	ClientType() string
}

// Header is the marker interface for a light client update message — either a
// header or a misbehaviour. Concrete update messages implement it so the
// lightclient.Interface can accept them opaquely; the client downcasts to its
// own concrete type.
type Header interface {
	ClientType() string
}

// StateUpdate is the result of a successful lightclient.Interface.VerifyHeader.
//
// It mirrors the Union (Rust) StateUpdate{height, client_state: Option,
// consensus_state}. The field shape matches ConsensusStateUpdate so the caller
// can persist it the same way. An empty ClientStateBytes means the client state
// did not change as part of this update (Rust's None client_state).
type StateUpdate struct {
	Height              uint64
	ConsensusStateBytes []byte
	ClientStateBytes    []byte
	StorageWrites       map[string][]byte
}

// ClientCreationResult is the result of lightclient.Interface.VerifyCreation.
//
// It mirrors the Union (Rust) ClientCreationResult{client_state: Option, ...}.
// An empty ClientStateBytes means the client state was not overwritten during
// creation. CometBLS performs no creation-time validation and writes nothing,
// so its result is empty; the type is kept for symmetry with other clients.
type ClientCreationResult struct {
	ClientStateBytes []byte
	StorageWrites    map[string][]byte
}

