package core

// MaxPacketDataEventSize returns the configured packet_data event budget after
// hexAttr encoding.
//
// The budget is MaxEventAttrPairs * MaxEventAttrValueLen and is enforced only
// when SplitEventAttrs is true.
func MaxPacketDataEventSize() int {
	config := GetEventConfig()
	return int(config.MaxEventAttrPairs * config.MaxEventAttrValueLen)
}

// IsValidPacketDataSize reports whether data stays within the configured
// packet_data event budget after hexAttr encoding.
//
// It returns true when SplitEventAttrs is false because that mode intentionally
// disables packet_data size checks.
func IsValidPacketDataSize(data []byte) bool {
	if !GetEventConfig().SplitEventAttrs {
		return true
	}

	return hexAttrLen(data) <= MaxPacketDataEventSize()
}

// eventColumnPairs returns the number of attr pairs encodedEventAttrs would
// emit for data: one "<key>_size" pair plus one pair per split column.
func eventColumnPairs(data []byte) int {
	maxValueLen := int(GetEventConfig().MaxEventAttrValueLen)
	columns := (hexAttrLen(data) + maxValueLen - 1) / maxValueLen
	if columns < 1 {
		columns = 1
	}

	return 1 + columns
}

// IsValidEventSize reports whether fields, split together into one host
// event, stay within chain.Emit's 64-attr-pair ceiling. Fields within
// IsValidPacketDataSize's solo budget individually can still exceed it
// combined, so MaxEventAttrPairs also serves as the shared pair budget here.
func IsValidEventSize(fields ...[]byte) bool {
	if !GetEventConfig().SplitEventAttrs {
		return true
	}

	total := 0
	for _, data := range fields {
		total += eventColumnPairs(data)
	}

	return total <= int(GetEventConfig().MaxEventAttrPairs)
}

package core

import (
	"strconv"

	"gno.land/p/onbloc/ibc/union/types"
)

// QueryClientState returns the client state bytes as a hex string, or an empty
// string when the client is missing.
func QueryClientState(clientId types.ClientId) string {
	bz, ok := store.ClientStateBytes(clientId)
	if !ok {
		return ""
	}

	return hexString(bz)
}

// QueryConsensusState returns the consensus state bytes at a given height as a
// hex string, or an empty string when missing.
func QueryConsensusState(clientId types.ClientId, height uint64) string {
	bz, ok := store.ConsensusStateBytes(clientId, types.NewHeight(height))
	if !ok {
		return ""
	}

	return hexString(bz)
}

// QueryConnection returns the ABI-encoded connection as a hex string, or an
// empty string when the connection is missing.
func QueryConnection(connectionId types.ConnectionId) string {
	conn, ok := store.GetConnection(connectionId)
	if !ok {
		return ""
	}
	bz, err := conn.EncodeABI()
	if err != nil {
		return ""
	}

	return hexString(bz)
}

// QueryChannel returns the ABI-encoded channel as a hex string, or an empty
// string when the channel is missing.
func QueryChannel(channelId types.ChannelId) string {
	channel, ok := store.GetChannel(channelId)
	if !ok {
		return ""
	}
	bz, err := channel.EncodeABI()
	if err != nil {
		return ""
	}

	return hexString(bz)
}

// GetClientStatus returns the client status as a uint8 string ("1"=Active,
// "2"=Expired, "3"=Frozen), or "0" when the client is missing.
func GetClientStatus(clientId types.ClientId) string {
	lc, ok := store.GetLightClient(clientId)
	if !ok {
		return strconv.FormatUint(uint64(types.StatusUnknown), 10)
	}

	return strconv.FormatUint(uint64(lc.Status().ToType()), 10)
}

