package core

import (
	"strings"

	"gno.land/r/onbloc/ibc/union/access"
)

// upgrade.gno is the single admin-gated swap point for the IBC host logic. The
// proxy keeps the Store and identity stable across upgrades; only `impl` changes.
//
// Activation note: core's public entrypoints delegate to the installed impl.
// The impl realm registers its constructor from init(), and UpdateImpl injects
// the proxy-owned Store before any delegated entrypoint can run.
var (
	currentImplPath  string
	currentImpl      ICore
	implConstructors map[string]func(store IStore) ICore
)

func init() {
	currentImpl = nil
	currentImplPath = ""
	implConstructors = make(map[string]func(store IStore) ICore)
}

func RegisterImpl(cur realm, constructor func(store IStore) ICore) {
	currentPath := cur.PkgPath()
	previousPath := cur.Previous().PkgPath()

	prefix := currentPath + "/"

	if !strings.HasPrefix(previousPath, prefix) {
		panic("previous impl path is not a prefix of the current impl path")
	}

	if _, ok := implConstructors[previousPath]; ok {
		panic("impl already registered")
	}

	implConstructors[previousPath] = constructor
}

// UpdateImpl installs or re-points the implementation. It is admin-gated and
// injects the proxy-owned store into the target, so the store needs no public
// getter — the only way to obtain it is through this gated install.
func UpdateImpl(cur realm, path string) {
	access.AssertCanCall(0, cur, SelectorUpdateImpl)

	constructor, ok := implConstructors[path]
	if !ok {
		panic("impl constructor not found")
	}

	currentImplPath = path
	currentImpl = constructor(store)
}

func mustGetImpl() ICore {
	if currentImpl == nil {
		panic("implementation not installed")
	}

	return currentImpl
}

package ucs03_zkgm

import (
	"time"

	tb "gno.land/p/onbloc/ibc/union/zkgm/tokenbucket"
	u256 "gno.land/p/onbloc/math/uint256"
	"gno.land/r/onbloc/ibc/union/access"
)

// SetBucketConfig creates or updates the per-denom send-side rate-limit bucket.
// The bucket is anchored to block time, so RefillRate is tokens per second.
func SetBucketConfig(cur realm, denom string, capacity *u256.Uint, refillRate *u256.Uint) {
	access.AssertCanCall(0, cur, SelectorSetBucketConfig)

	bucket, ok := store.GetTokenBucket(denom)
	if !ok {
		newBucket, err := tb.New(capacity, refillRate, u256.NewUint(uint64(time.Now().Unix())))
		if err != nil {
			panic(err)
		}

		store.SetTokenBucket(0, cur, denom, newBucket)
		emitZkgmRateLimitBucketConfiguredEvent(cur.Previous().Address(), denom, capacity, refillRate)

		return
	}

	err := bucket.Update(capacity, refillRate, false)
	if err != nil {
		panic(err)
	}

	emitZkgmRateLimitBucketConfiguredEvent(cur.Previous().Address(), denom, capacity, refillRate)
}

// SetRateLimitDisabled toggles the global rate-limit kill switch.
func SetRateLimitDisabled(cur realm, disabled bool) {
	access.AssertCanCall(0, cur, SelectorSetRateLimitDisabled)
	store.SetRateLimitDisabled(0, cur, disabled)
	emitZkgmRateLimitDisabledSetEvent(cur.Previous().Address(), disabled)
}

// Pausable toggles the global pause gate checked by every App receiver.
func Pausable(cur realm, p bool) {
	access.AssertCanCall(0, cur, SelectorPausable)
	paused = p
	if p {
		emitZkgmPausedEvent(cur.Previous().Address())
	} else {
		emitZkgmUnpausedEvent(cur.Previous().Address())
	}
}

package ucs03_zkgm

import (
	app "gno.land/p/onbloc/ibc/union/app"
	types "gno.land/p/onbloc/ibc/union/types"
)

// app.gno is the App receiver surface: the core-driven half of the proxy. core
// holds this App reference permanently (its port is keyed by the proxy pkgpath
// and re-registration is rejected), so App is the stable IBC identity and must
// never carry business logic. Every receiver gates on assertIsCoreRealm and
// assertIsNotPaused before delegating to the installed impl or rejecting channel
// close. Logic lives in the impl realm; authority and funds live in the proxy.
// See assert.gno for the gates and upgrade.gno for the swap point.
type App struct{}

var (
	_ app.IApp       = &App{}
	_ app.IIntentApp = &App{}
)

func (a *App) OnChannelOpenInit(cur realm, connectionId types.ConnectionId, channelId types.ChannelId, version string, relayer address) {
	assertIsCoreRealm(cur)
	assertIsNotPaused()

	mustGetImpl().OnChannelOpenInit(0, cur, connectionId, channelId, version, relayer)
}

func (a *App) OnChannelOpenTry(cur realm, connectionId types.ConnectionId, channelId types.ChannelId, version string, counterpartyVersion string, relayer address) {
	assertIsCoreRealm(cur)
	assertIsNotPaused()

