package core

import (
	"gno.land/p/onbloc/ibc/union/types"
	core "gno.land/r/onbloc/ibc/union/core"
)

// channel.gno: channel handshake and close logic. The admin gate stays on the
// proxy entrypoint; the Force* recovery variants remain proxy admin operations.
// Each handshake step dispatches the matching callback to the channel's app.

// ChannelOpenInit starts a channel in the Init state and notifies its app. The
// created channel id is observable through the emitted event, not returned.
func (c *coreV1) ChannelOpenInit(_ int, rlm realm, msg types.MsgChannelOpenInit) {
	assertIsRlmCurrent(0, rlm)

	relayer := rlm.Previous().Address()
	portId := types.Bytes(types.CloneBytes(msg.PortId))
	connection := c.ensureConnectionState(msg.ConnectionId)
	channelId := c.store.NextChannelId(0, rlm)

	channel := core.NewChannel(
		types.ChannelStateInit,
		msg.ConnectionId,
		0,
		types.Bytes(types.CloneBytes(msg.CounterpartyPortId)),
		msg.Version,
	)
	c.store.CreateChannel(0, rlm, channelId, channel, portId)

	a, err := c.getAppAtPort(portId)
	if err != nil {
		panic(err)
	}

	a.OnChannelOpenInit(cross(rlm), msg.ConnectionId, channelId, msg.Version, relayer)
	core.EmitChannelOpenInit(0, rlm, portId, channelId, channel, connection)
}

// ChannelOpenTry proves a counterparty Init and opens the local channel in
// TryOpen, notifying its app.
func (c *coreV1) ChannelOpenTry(_ int, rlm realm, msg types.MsgChannelOpenTry) {
	assertIsRlmCurrent(0, rlm)

	c.channelOpenTry(0, rlm, msg, true)
}

// ForceChannelOpenTry is the admin recovery variant of ChannelOpenTry that skips
// counterparty proof verification.
func (c *coreV1) ForceChannelOpenTry(_ int, rlm realm, msg types.MsgChannelOpenTry) {
	assertIsRlmCurrent(0, rlm)

	c.channelOpenTry(0, rlm, msg, false)
}

func (c *coreV1) channelOpenTry(_ int, rlm realm, msg types.MsgChannelOpenTry, verify bool) {
	relayer := rlm.Previous().Address()
	portId := types.Bytes(types.CloneBytes(msg.PortId))
	if msg.Channel.State != types.ChannelStateTryOpen {
		panic(makeError(core.ErrInvalidChannelState))
	}

	if msg.Channel.CounterpartyChannelId == 0 {
		panic(makeError(core.ErrInvalidCounterpartyChannelId))
	}

	connection := c.ensureConnectionState(msg.Channel.ConnectionId)
	channelId := c.store.NextChannelId(0, rlm)

	if verify {
		expectedChannel := core.NewChannel(
			types.ChannelStateInit,
			connection.CounterpartyConnectionId,
			0,
			portId,
			msg.CounterpartyVersion,
		)
		key := types.ChannelPath(msg.Channel.CounterpartyChannelId)
		value := core.ChannelValue(expectedChannel)
		c.verifyMembership(connection.ClientId, types.NewHeight(msg.ProofHeight), msg.ProofInit, key[:], value[:])
	}

	c.store.CreateChannel(0, rlm, channelId, msg.Channel, portId)

	a, err := c.getAppAtPort(portId)
	if err != nil {
		panic(err)
	}

	a.OnChannelOpenTry(cross(rlm), msg.Channel.ConnectionId, channelId, msg.Channel.Version, msg.CounterpartyVersion, relayer)

	core.EmitChannelOpenTry(0, rlm, portId, channelId, msg.Channel, msg.CounterpartyVersion, connection)
}

// ChannelOpenAck proves the counterparty TryOpen and moves the local Init
// channel to Open, notifying its app.
func (c *coreV1) ChannelOpenAck(_ int, rlm realm, msg types.MsgChannelOpenAck) {
	assertIsRlmCurrent(0, rlm)

	c.channelOpenAck(0, rlm, msg, true)
}

// ForceChannelOpenAck is the admin recovery variant of ChannelOpenAck that skips
// counterparty proof verification.
func (c *coreV1) ForceChannelOpenAck(_ int, rlm realm, msg types.MsgChannelOpenAck) {
	assertIsRlmCurrent(0, rlm)

	c.channelOpenAck(0, rlm, msg, false)
}

func (c *coreV1) channelOpenAck(_ int, rlm realm, msg types.MsgChannelOpenAck, verify bool) {
	relayer := rlm.Previous().Address()

	channel, err := c.getChannel(msg.ChannelId)
	if err != nil {
		panic(err)
	}

	if channel.State != types.ChannelStateInit {
		panic(makeError(core.ErrInvalidChannelState))
	}

	connection := c.ensureConnectionState(channel.ConnectionId)
	portId, _ := c.store.GetChannelOwner(msg.ChannelId)

	if verify {
		expectedChannel := core.NewChannel(
			types.ChannelStateTryOpen,
			connection.CounterpartyConnectionId,
			msg.ChannelId,
			portId,
			msg.CounterpartyVersion,
		)
		key := types.ChannelPath(msg.CounterpartyChannelId)
		value := core.ChannelValue(expectedChannel)
		c.verifyMembership(connection.ClientId, types.NewHeight(msg.ProofHeight), msg.ProofTry, key[:], value[:])
	}

	updated := core.NewChannel(
		types.ChannelStateOpen,
		channel.ConnectionId,
		msg.CounterpartyChannelId,
		channel.CounterpartyPortId.Clone(),
		msg.CounterpartyVersion,
	)
	c.store.SaveChannel(0, rlm, msg.ChannelId, updated)

	a, err := c.getAppAtPort(portId)
	if err != nil {
		panic(err)
	}

	a.OnChannelOpenAck(cross(rlm), msg.ChannelId, msg.CounterpartyChannelId, msg.CounterpartyVersion, relayer)

	core.EmitChannelOpenAck(0, rlm, portId, msg.ChannelId, updated, connection)
}

// ChannelOpenConfirm proves the counterparty Open and moves the local TryOpen
// channel to Open, notifying its app.
func (c *coreV1) ChannelOpenConfirm(_ int, rlm realm, msg types.MsgChannelOpenConfirm) {
	assertIsRlmCurrent(0, rlm)

	c.channelOpenConfirm(0, rlm, msg, true)
}

// ForceChannelOpenConfirm is the admin recovery variant of ChannelOpenConfirm
// that skips counterparty proof verification.
func (c *coreV1) ForceChannelOpenConfirm(_ int, rlm realm, msg types.MsgChannelOpenConfirm) {
	assertIsRlmCurrent(0, rlm)

	c.channelOpenConfirm(0, rlm, msg, false)
}

func (c *coreV1) channelOpenConfirm(_ int, rlm realm, msg types.MsgChannelOpenConfirm, verify bool) {
	relayer := rlm.Previous().Address()

	channel, err := c.getChannel(msg.ChannelId)
	if err != nil {
		panic(err)
	}

	if channel.State != types.ChannelStateTryOpen {
		panic(makeError(core.ErrInvalidChannelState))
	}

	if channel.CounterpartyChannelId == 0 {
		panic(makeError(core.ErrInvalidCounterpartyChannelId))
	}

	connection := c.ensureConnectionState(channel.ConnectionId)
	portId, _ := c.store.GetChannelOwner(msg.ChannelId)

	if verify {
		expectedChannel := core.NewChannel(
			types.ChannelStateOpen,
			connection.CounterpartyConnectionId,
			msg.ChannelId,
			portId,
			channel.Version,
		)
		key := types.ChannelPath(channel.CounterpartyChannelId)
		value := core.ChannelValue(expectedChannel)
		c.verifyMembership(connection.ClientId, types.NewHeight(msg.ProofHeight), msg.ProofAck, key[:], value[:])
	}

	updated := core.NewChannel(
		types.ChannelStateOpen,
		channel.ConnectionId,
		channel.CounterpartyChannelId,
		channel.CounterpartyPortId.Clone(),
		channel.Version,
	)
	c.store.SaveChannel(0, rlm, msg.ChannelId, updated)

	a, err := c.getAppAtPort(portId)
	if err != nil {
		panic(err)
	}

	a.OnChannelOpenConfirm(cross(rlm), msg.ChannelId, relayer)

	core.EmitChannelOpenConfirm(0, rlm, portId, msg.ChannelId, updated, connection)
}

// ChannelCloseInit closes an Open channel locally and notifies its app.
func (c *coreV1) ChannelCloseInit(_ int, rlm realm, msg types.MsgChannelCloseInit) {
	assertIsRlmCurrent(0, rlm)

	relayer := rlm.Previous().Address()

	channel, err := c.getChannel(msg.ChannelId)
	if err != nil {
		panic(err)
	}

	if channel.State != types.ChannelStateOpen {
		panic(makeError(core.ErrInvalidChannelState))
	}

	if channel.CounterpartyChannelId == 0 {
		panic(makeError(core.ErrInvalidCounterpartyChannelId))
	}

	connection := c.ensureConnectionState(channel.ConnectionId)
	portId, _ := c.store.GetChannelOwner(msg.ChannelId)

	updated := c.closedChannel(channel)
	c.store.SaveChannel(0, rlm, msg.ChannelId, updated)

	a, ok := c.store.GetAppByPortId(portId)
	if !ok {
		panic("port " + string(portId) + " not found")
	}
	a.OnChannelCloseInit(cross(rlm), msg.ChannelId, relayer)
	core.EmitChannelCloseInit(0, rlm, portId, msg.ChannelId, updated, connection)
}

// ChannelCloseConfirm proves the counterparty Closed and closes the local
// channel, notifying its app.
func (c *coreV1) ChannelCloseConfirm(_ int, rlm realm, msg types.MsgChannelCloseConfirm) {
	assertIsRlmCurrent(0, rlm)

	relayer := rlm.Previous().Address()

	channel, err := c.getChannel(msg.ChannelId)
	if err != nil {
		panic(err)
	}

	if channel.State != types.ChannelStateOpen {
		panic(makeError(core.ErrInvalidChannelState))
	}

	if channel.CounterpartyChannelId == 0 {
		panic(makeError(core.ErrInvalidCounterpartyChannelId))
	}

	connection := c.ensureConnectionState(channel.ConnectionId)
	portId, _ := c.store.GetChannelOwner(msg.ChannelId)

	expectedChannel := core.NewChannel(
		types.ChannelStateClosed,
		connection.CounterpartyConnectionId,
		msg.ChannelId,
		portId,
		channel.Version,
	)
	key := types.ChannelPath(channel.CounterpartyChannelId)
	value := core.ChannelValue(expectedChannel)
	c.verifyMembership(connection.ClientId, types.NewHeight(msg.ProofHeight), msg.ProofInit, key[:], value[:])

	updated := c.closedChannel(channel)
	c.store.SaveChannel(0, rlm, msg.ChannelId, updated)

	a, ok := c.store.GetAppByPortId(portId)
	if !ok {
		panic("port " + string(portId) + " not found")
	}
	a.OnChannelCloseConfirm(cross(rlm), msg.ChannelId, relayer)
	core.EmitChannelCloseConfirm(0, rlm, portId, msg.ChannelId, updated, connection)
}

// closedChannel returns a Closed copy of channel without mutating the store-owned
// value.
func (c *coreV1) closedChannel(channel types.Channel) types.Channel {
	return core.NewChannel(
		types.ChannelStateClosed,
		channel.ConnectionId,
		channel.CounterpartyChannelId,
		channel.CounterpartyPortId.Clone(),
		channel.Version,
	)
}

// getChannel returns the stored channel for channelId, or an error when it is
// missing. It centralizes the lookup shared by the handshake and packet paths;
// the caller (entrypoint) decides whether a miss reverts.
func (c *coreV1) getChannel(channelId types.ChannelId) (types.Channel, error) {
	channel, ok := c.store.GetChannel(channelId)
	if !ok {
		return types.Channel{}, makeError(core.ErrChannelNotFound, channelId.String())
	}

	return channel, nil
}

package core

import (
	"gno.land/p/onbloc/ibc/union/lightclient"
	"gno.land/p/onbloc/ibc/union/types"
	core "gno.land/r/onbloc/ibc/union/core"
)

// RegisterClient stores a light client implementation for a client type.
// CreateClient calls it to produce a fresh instance from the submitted state
// bytes. Callers that pass nil are rejected as unauthorized.
// Union reference:
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/core/src/contract.rs#L849-L865
func (c *coreV1) RegisterClient(_ int, rlm realm, clientType types.ClientType, clientImpl lightclient.ClientImpl) {
	assertIsRlmCurrent(0, rlm)

	if clientImpl == nil {
		panic("caller not authorized to register client: unauthorized")
	}
	c.store.RegisterClient(0, rlm, clientType, clientImpl)
	core.EmitRegisterClient(0, rlm, clientType)
}

// HasClient reports whether a light client is registered for a client type.
func (c *coreV1) HasClient(clientType types.ClientType) bool {
	return c.store.HasRegisteredClient(clientType)
}

// CreateClient assigns a client id for a registered light client type, stores
// the submitted state bytes, then lets the light client verify creation against
// that freshly stored state.
func (c *coreV1) CreateClient(_ int, rlm realm, msg types.MsgCreateClient) {
	assertIsRlmCurrent(0, rlm)

	creator := rlm.Previous().Address()
	relayer := resolveRelayer(creator, msg.Relayer)

	clientImpl, ok := c.store.ClientRegistry(msg.ClientType)
	if !ok {
		panic("client type not found")
	}

	lc, err := clientImpl(msg.ClientStateBytes, msg.ConsensusStateBytes)
	if err != nil {
		panic("create client: " + err.Error())
	}

	clientId := c.store.AddClient(0, rlm, msg.ClientType, creator, lc)
	c.initClient(0, rlm, clientId, msg.ClientStateBytes, msg.ConsensusStateBytes, relayer)

	core.EmitCreateClient(0, rlm, clientId, msg.ClientType, lc.GetCounterpartyChainID())
}

// initClient mirrors the submitted client/consensus state for a stored client,
// runs the light client's creation verification, then persists any state
// overwrite and storage writes the verification returns. It returns the height
// the consensus state was stored at.
func (c *coreV1) initClient(_ int, rlm realm, clientId types.ClientId, clientStateBytes, consensusStateBytes []byte, relayer address) types.Height {
	lc, ok := c.store.GetLightClient(clientId)
	if !ok {
		panic("client " + clientId.String() + " not found")
	}

	c.store.SaveClientState(0, rlm, clientId, clientStateBytes)

	height := types.NewHeight(lc.GetLatestHeight())
	c.store.SaveConsensusState(0, rlm, clientId, height, consensusStateBytes)

	// union threads info.sender as the caller; gno derives the authenticated
	// caller from the realm (internal calls preserve the entry frame).
	result, err := lc.VerifyCreation(rlm.Previous().Address(), relayer)
	if err != nil {
		panic("create client: " + err.Error())
	}

	if len(result.ClientStateBytes) != 0 {
		c.store.SaveClientState(0, rlm, clientId, result.ClientStateBytes)
	}

	for k, v := range result.StorageWrites {
		c.store.SaveClientStore(0, rlm, clientId, k, v)
	}

	return height
}

// UpdateClient verifies a client message against the light client object, which
// updates its own state, and mirrors the resulting state bytes for queries and
// counterparty proofs.
func (c *coreV1) UpdateClient(_ int, rlm realm, msg types.MsgUpdateClient) {
	assertIsRlmCurrent(0, rlm)

	lc, err := c.getActiveClient(msg.ClientId)
	if err != nil {
		panic(err)
	}

	caller := rlm.Previous().Address()
	relayer := resolveRelayer(caller, msg.Relayer)

	update, err := lc.VerifyHeader(caller, msg.ClientMessage, relayer)
	if err != nil {
		panic("update client: " + err.Error())
	}

	height := types.NewHeight(update.Height)

	if len(update.ClientStateBytes) != 0 {
		c.store.SaveClientState(0, rlm, msg.ClientId, update.ClientStateBytes)
	}

	// Union stores consensus_state_bytes unconditionally because the field is not
	// optional in the update response.
	c.store.SaveConsensusState(0, rlm, msg.ClientId, height, update.ConsensusStateBytes)

	for k, v := range update.StorageWrites {
		c.store.SaveClientStore(0, rlm, msg.ClientId, k, v)
	}

	core.EmitUpdateClient(0, rlm, msg.ClientId, height)
}

func (c *coreV1) ForceUpdateClient(_ int, rlm realm, msg types.MsgForceUpdateClient) {
	assertIsRlmCurrent(0, rlm)

	clientImpl, ok := c.store.GetClientImpl(msg.ClientId)
	if !ok {
		panic(makeError(core.ErrClientNotFound, msg.ClientId.String()))
	}

	next, err := clientImpl(msg.ClientStateBytes, msg.ConsensusStateBytes)
	if err != nil {
		panic("force update client: " + err.Error())
	}

	c.store.SetLightClient(0, rlm, msg.ClientId, next)

	caller := rlm.Previous().Address()
	height := c.initClient(0, rlm, msg.ClientId, msg.ClientStateBytes, msg.ConsensusStateBytes, caller)

	core.EmitForceUpdateClient(0, rlm, msg.ClientId, height)
}

// Misbehaviour verifies a misbehaviour message against an active light client and
// freezes it. Mirroring union (contract.rs L1048-L1093), the host commits the
// frozen client-state bytes the light client returns back to the client-state
// mirror / ClientStatePath commitment before emitting the event.
// reference: https://github.com/unionlabs/union/blob/d91c5e94354e15801bd5f82dc658eae3b79f2dad/cosmwasm/core/src/contract.rs#L1048-L1093
func (c *coreV1) Misbehaviour(_ int, rlm realm, msg types.MsgMisbehaviour) {
	assertIsRlmCurrent(0, rlm)

	lc, err := c.getActiveClient(msg.ClientId)
	if err != nil {
		panic(err)
	}

	caller := rlm.Previous().Address()
	relayer := resolveRelayer(caller, msg.Relayer)

	clientStateBytes, err := lc.Misbehaviour(caller, msg.ClientMessage, relayer)
	if err != nil {
		panic("misbehaviour: " + err.Error())
	}

	if len(clientStateBytes) != 0 {
		c.store.SaveClientState(0, rlm, msg.ClientId, clientStateBytes)
	}

	core.EmitMisbehaviour(0, rlm, msg.ClientId)
}

// verifyMembership checks a membership proof against a registered, active light
// client. Shared by the connection/channel handshakes.
func (c *coreV1) verifyMembership(clientId types.ClientId, height types.Height, proof, key, value []byte) {
	lc, err := c.getActiveClient(clientId)
	if err != nil {
		panic(err)
	}

	err = lc.VerifyMembership(height.RevisionHeight, key, proof, value)
	if err != nil {
		panic(err)
	}
}

// getClient returns the light client registered under clientId, or an error
// when no client is registered for it. The caller (entrypoint) decides whether
// a miss reverts.
func (c *coreV1) getClient(clientId types.ClientId) (lightclient.Interface, error) {
	lc, ok := c.store.GetLightClient(clientId)
	if !ok {
		return nil, makeError(core.ErrClientNotFound, clientId.String())
	}

	return lc, nil
}

// getActiveClient returns the light client registered under clientId, or an
// error when it is missing or not in the Active status. It centralizes the
// "registered and active" precondition shared by the update, misbehaviour, and
// proof-verification paths.
func (c *coreV1) getActiveClient(clientId types.ClientId) (lightclient.Interface, error) {
	lc, err := c.getClient(clientId)
	if err != nil {
		return nil, err
	}

	if lc.Status() != lightclient.Active {
		return nil, makeError(core.ErrClientNotActive)
	}

	return lc, nil
}

package core

import (
	"gno.land/p/onbloc/ibc/union/types"
	core "gno.land/r/onbloc/ibc/union/core"
)

// connection.gno: the connection handshake logic. The admin gate stays on the
// proxy entrypoint; this realm holds the protocol logic. The Force* recovery
// variants (no proof verification) remain on the proxy as admin operations.

// ConnectionOpenInit starts a connection in the Init state.
func (c *coreV1) ConnectionOpenInit(_ int, rlm realm, msg types.MsgConnectionOpenInit) {
	assertIsRlmCurrent(0, rlm)

	connectionId := c.store.NextConnectionId(0, rlm)
	connection := core.NewConnection(types.ConnectionStateInit, msg.ClientId, msg.CounterpartyClientId, 0)
	c.store.SaveConnection(0, rlm, connectionId, connection)
	core.EmitConnectionOpenInit(0, rlm, connectionId, msg.ClientId, msg.CounterpartyClientId)
}

// ConnectionOpenTry acknowledges a counterparty Init by proving it and moving to
// TryOpen.
func (c *coreV1) ConnectionOpenTry(_ int, rlm realm, msg types.MsgConnectionOpenTry) {
	assertIsRlmCurrent(0, rlm)

	c.connectionOpenTry(0, rlm, msg, true)
}

// ForceConnectionOpenTry is the admin recovery variant of ConnectionOpenTry that
// skips counterparty proof verification.
func (c *coreV1) ForceConnectionOpenTry(_ int, rlm realm, msg types.MsgConnectionOpenTry) {
	assertIsRlmCurrent(0, rlm)

	c.connectionOpenTry(0, rlm, msg, false)
}

func (c *coreV1) connectionOpenTry(_ int, rlm realm, msg types.MsgConnectionOpenTry, verify bool) {
	connectionId := c.store.NextConnectionId(0, rlm)
	connection := core.NewConnection(types.ConnectionStateTryOpen, msg.ClientId, msg.CounterpartyClientId, msg.CounterpartyConnectionId)

	if verify {
		expectedConnection := core.NewConnection(types.ConnectionStateInit, msg.CounterpartyClientId, msg.ClientId, 0)
		key := types.ConnectionPath(msg.CounterpartyConnectionId)
		value := core.ConnectionValue(expectedConnection)
		c.verifyMembership(msg.ClientId, types.NewHeight(msg.ProofHeight), msg.ProofInit, key[:], value[:])
	}

	c.store.SaveConnection(0, rlm, connectionId, connection)
	core.EmitConnectionOpenTry(0, rlm, connectionId, msg.ClientId, msg.CounterpartyClientId, msg.CounterpartyConnectionId)
}

// ConnectionOpenAck proves the counterparty TryOpen and moves the local Init
// connection to Open.
func (c *coreV1) ConnectionOpenAck(_ int, rlm realm, msg types.MsgConnectionOpenAck) {
	assertIsRlmCurrent(0, rlm)

	c.connectionOpenAck(0, rlm, msg, true)
}

// ForceConnectionOpenAck is the admin recovery variant of ConnectionOpenAck that
// skips counterparty proof verification.
func (c *coreV1) ForceConnectionOpenAck(_ int, rlm realm, msg types.MsgConnectionOpenAck) {
	assertIsRlmCurrent(0, rlm)

	c.connectionOpenAck(0, rlm, msg, false)
}

func (c *coreV1) connectionOpenAck(_ int, rlm realm, msg types.MsgConnectionOpenAck, verify bool) {
	connection, ok := c.store.GetConnection(msg.ConnectionId)
	if !ok {
		panic(makeError(core.ErrConnectionNotFound, msg.ConnectionId.String()))
	}

	if connection.State != types.ConnectionStateInit {
		panic(makeError(core.ErrInvalidConnectionState))
	}

	if verify {
		expectedConnection := core.NewConnection(types.ConnectionStateTryOpen, connection.CounterpartyClientId, connection.ClientId, msg.ConnectionId)
		key := types.ConnectionPath(msg.CounterpartyConnectionId)
		value := core.ConnectionValue(expectedConnection)
		c.verifyMembership(connection.ClientId, types.NewHeight(msg.ProofHeight), msg.ProofTry, key[:], value[:])
	}

	// Build a fresh connection rather than mutating the store-owned one (the
	// retrieved value is read-only under the borrow rule).
	updated := core.NewConnection(types.ConnectionStateOpen, connection.ClientId, connection.CounterpartyClientId, msg.CounterpartyConnectionId)
	c.store.SaveConnection(0, rlm, msg.ConnectionId, updated)

	core.EmitConnectionOpenAck(0, rlm, msg.ConnectionId, connection.ClientId, connection.CounterpartyClientId, msg.CounterpartyConnectionId)
}

// ConnectionOpenConfirm proves the counterparty Open and moves the local TryOpen
// connection to Open.
func (c *coreV1) ConnectionOpenConfirm(_ int, rlm realm, msg types.MsgConnectionOpenConfirm) {
	assertIsRlmCurrent(0, rlm)

	c.connectionOpenConfirm(0, rlm, msg, true)
}

// ForceConnectionOpenConfirm is the admin recovery variant of
// ConnectionOpenConfirm that skips counterparty proof verification.
func (c *coreV1) ForceConnectionOpenConfirm(_ int, rlm realm, msg types.MsgConnectionOpenConfirm) {
	assertIsRlmCurrent(0, rlm)

	c.connectionOpenConfirm(0, rlm, msg, false)
}

func (c *coreV1) connectionOpenConfirm(_ int, rlm realm, msg types.MsgConnectionOpenConfirm, verify bool) {
	connection, ok := c.store.GetConnection(msg.ConnectionId)
	if !ok {
		panic(makeError(core.ErrConnectionNotFound, msg.ConnectionId.String()))
	}

	if connection.State != types.ConnectionStateTryOpen {
		panic(makeError(core.ErrInvalidConnectionState))
	}

	counterpartyConnectionId := connection.CounterpartyConnectionId

	if verify {
		expectedConnection := core.NewConnection(types.ConnectionStateOpen, connection.CounterpartyClientId, connection.ClientId, msg.ConnectionId)
		key := types.ConnectionPath(counterpartyConnectionId)
		value := core.ConnectionValue(expectedConnection)
		c.verifyMembership(connection.ClientId, types.NewHeight(msg.ProofHeight), msg.ProofAck, key[:], value[:])
	}

	// Build a fresh connection rather than mutating the store-owned one.
	updated := core.NewConnection(types.ConnectionStateOpen, connection.ClientId, connection.CounterpartyClientId, counterpartyConnectionId)
	c.store.SaveConnection(0, rlm, msg.ConnectionId, updated)

	core.EmitConnectionOpenConfirm(0, rlm, msg.ConnectionId, connection.ClientId, connection.CounterpartyClientId, counterpartyConnectionId)
}

// ensureConnectionState returns the connection for connectionId, requiring it to
// be Open.
func (c *coreV1) ensureConnectionState(connectionId types.ConnectionId) types.Connection {
	connection, ok := c.store.GetConnection(connectionId)
	if !ok {
		panic(makeError(core.ErrConnectionNotFound, connectionId.String()))
	}

	if connection.State != types.ConnectionStateOpen {
		panic(makeError(core.ErrInvalidConnectionState))
	}

	return connection
}

package core

import (
	"errors"
	"strings"
)

// ErrSpoofedRealm guards non-crossing (_ int, rlm realm, ...) entrypoints: the
// passed rlm must be the current crossing frame, not a forged or stale token.
const errSpoofedRealm = "rlm does not match the current crossing frame"

// makeError builds a fresh error from one or more message parts joined by ", ".
// Errors are constructed at the call site (never shared package-level values) so
// the resulting object is owned by this (impl) realm rather than the realm that
// declared a shared sentinel. The base message constant comes first and any
// value-carrying detail after, e.g. makeError(core.ErrChannelNotFound, id.String()).
func makeError(msgs ...string) error {
	return errors.New(strings.Join(msgs, ", "))
}

package core

import (
	"gno.land/p/onbloc/ibc/union/lightclient"
	"gno.land/p/onbloc/ibc/union/types"
	core "gno.land/r/onbloc/ibc/union/core"
)

// getters.gno implements the read-only ICoreGetter surface. Results read the
// injected store / light client. Queries that fail on a missing lookup
// (client/consensus/connection/channel state, status, latest height, timestamp,
// batch commitments) return an error rather than a found-bool or a panic.

// GetLightClient returns the live light client instance for a client, or
// (nil, false) when the client is missing.
func (c *coreV1) GetLightClient(clientId types.ClientId) (lightclient.Interface, bool) {
	return c.store.GetLightClient(clientId)
}

// GetStatus returns the client's status, or an error when the client is missing.
func (c *coreV1) GetStatus(clientId types.ClientId) (types.Status, error) {
	lc, ok := c.store.GetLightClient(clientId)
	if !ok {
		return types.StatusUnknown, makeError(core.ErrClientNotFound)
	}

	return lc.Status().ToType(), nil
}

// GetClientType returns the registered client type for a client, or an error
// when the client is missing.
func (c *coreV1) GetClientType(clientId types.ClientId) (types.ClientType, error) {
	typ, ok := c.store.ClientType(clientId)
	if !ok {
		return "", makeError(core.ErrClientNotFound)
	}

	return typ, nil
}

// GetClientImpl is best-effort: gno has no client_type->impl address mapping, so
// it returns the registered client type as the impl identifier, or an error when
// the client is missing.
func (c *coreV1) GetClientImpl(clientId types.ClientId) (string, error) {
	typ, ok := c.store.ClientType(clientId)
	if !ok {
		return "", makeError(core.ErrClientNotFound)
	}

	return string(typ), nil
}

// GetRegisteredClientType reports whether a light client implementation is
// registered for the given client type.
