package ucs03_zkgm

func assertIsRlmCurrent(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic(errSpoofedRealm)
	}
}

package ucs03_zkgm

import (
	types "gno.land/p/onbloc/ibc/union/types"

	z "gno.land/p/onbloc/ibc/union/zkgm"
	u256 "gno.land/p/onbloc/math/uint256"
)

// verifyBatch verifies each allowed child instruction against the shared funds budget.
// reference: https://github.com/unionlabs/union/blob/d91c5e94354e15801bd5f82dc658eae3b79f2dad/cosmwasm/app/ucs03-zkgm/src/contract.rs#L2941-L2967
func (v *ucs03ZkgmV1) verifyBatch(_ int, rlm realm, funds *funds, channelId types.ChannelId, path *u256.Uint, batch z.Batch) error {
	for _, instruction := range batch.Instructions {
		if !isAllowedBatchInstruction(instruction.Opcode) {
			return makeError(errInvalidBatchInstruction)
		}

		if err := v.verifyInternal(0, rlm, funds, channelId, path, instruction); err != nil {
			return err
		}
	}

	return nil
}

// executeBatch runs each child in order, aborting the whole batch on an only-maker child.
// reference: https://github.com/unionlabs/union/blob/d91c5e94354e15801bd5f82dc658eae3b79f2dad/cosmwasm/app/ucs03-zkgm/src/contract.rs#L1686-L1726
func (v *ucs03ZkgmV1) executeBatch(_ int, rlm realm, packet types.Packet, relayer address, relayerMsg []byte, salt [32]byte, path *u256.Uint, batch z.Batch, intent bool) ([]byte, error) {
	acks := make([][]byte, len(batch.Instructions))

	// NOTE: batch.Instructions remains uncapped until the Union reference defines
	// a maximum. Each child runs dispatchExecutePacket, including ABI decode and
	// keccak work, so execution cost scales with child count.
	for i, instruction := range batch.Instructions {
		if !isAllowedBatchInstruction(instruction.Opcode) {
			panic(execFatal{makeError(errInvalidBatchInstruction).Error()})
		}

		childSalt := z.DeriveBatchSalt(u256.NewUint(uint64(i)), salt)

		childRes, err := v.dispatchExecutePacket(0, rlm, packet, relayer, relayerMsg, childSalt, path, instruction, intent)
		if err != nil {
			panic(execFatal{err.Error()})
		}

		childAck := childRes.Acknowledgement
		if len(childAck) == 0 {
			// empty ack is unrecoverable once earlier children have committed.
			panic(execFatal{"batch child returned empty ack"})
		}
		// A single only-maker child aborts the entire batch: return the sentinel up
		// to the recv boundary (OnRecvPacket / OnIntentRecvPacket), which panics on
		// it and reverts the whole recv tx — so already-processed children's
		// mutations do NOT stand. Mirrors union's reply handler returning
		// Err(OnlyMaker) on an only-maker batch ack (contract.rs L2528-2530).
		if isOnlyMakerAck(childAck) {
			return types.CloneBytes(z.ACK_ERR_ONLY_MAKER), nil
		}

		acks[i] = childAck
	}

	batchAckBytes, err := z.EncodeBatchAck(z.BatchAck{Acknowledgements: acks})
	if err != nil {
		panic(execFatal{err.Error()})
	}

	ack, err := z.EncodeAck(z.Ack{Tag: tagAckSuccess(), InnerAck: batchAckBytes})
	if err != nil {
		panic(execFatal{err.Error()})
	}

	return ack, nil
}

// acknowledgeBatch fans the outer ack out to each child instruction.
func (v *ucs03ZkgmV1) acknowledgeBatch(_ int, rlm realm, packet types.Packet, relayer address, salt [32]byte, path *u256.Uint, batch z.Batch, successful bool, ack []byte) error {
	var batchAck z.BatchAck

	if successful {
		decoded, err := z.DecodeBatchAck(ack)
		if err != nil {
			return err
		}

		batchAck = decoded
		if len(batchAck.Acknowledgements) != len(batch.Instructions) {
			return makeError(errBatchAckCountMismatch)
		}
	}

	for i, instruction := range batch.Instructions {
		var childAck []byte

		childSuccessful := successful

		if successful {
			decodedChildAck, err := z.DecodeAck(batchAck.Acknowledgements[i])
			if err != nil {
				return err
			}

			childSuccessful = decodedChildAck.Tag != nil && decodedChildAck.Tag.Eq(tagAckSuccess())
			childAck = decodedChildAck.InnerAck
		}

		childSalt := z.DeriveBatchSalt(u256.NewUint(uint64(i)), salt)
		if err := v.acknowledgeInternal(0, rlm, packet, relayer, childSalt, path, instruction, childSuccessful, childAck); err != nil {
			return err
		}
	}

	return nil
}

// timeoutBatch fans the timeout out to each child instruction.
func (v *ucs03ZkgmV1) timeoutBatch(_ int, rlm realm, packet types.Packet, salt [32]byte, path *u256.Uint, batch z.Batch) error {
	for i, instruction := range batch.Instructions {
		childSalt := z.DeriveBatchSalt(u256.NewUint(uint64(i)), salt)
		if err := v.timeoutInternal(0, rlm, packet, childSalt, path, instruction); err != nil {
			return err
		}
	}

	return nil
}

// isAllowedBatchInstruction reports whether opcode may appear in a batch.
func isAllowedBatchInstruction(opcode uint8) bool {
	return opcode == z.OP_CALL || opcode == z.OP_TOKEN_ORDER
}

package ucs03_zkgm

import (
	types "gno.land/p/onbloc/ibc/union/types"

	z "gno.land/p/onbloc/ibc/union/zkgm"
	u256 "gno.land/p/onbloc/math/uint256"
	core "gno.land/r/onbloc/ibc/union/core"
)

// verifyCall rejects eureka mode and requires the call sender to match the dispatch sender.
// reference: https://github.com/unionlabs/union/blob/d91c5e94354e15801bd5f82dc658eae3b79f2dad/cosmwasm/app/ucs03-zkgm/src/contract.rs#L2997-L3019
func (v *ucs03ZkgmV1) verifyCall(_ int, rlm realm, call z.Call) error {
	if call.Eureka {
		return makeError(errEurekaUnsupported)
	}

	if string(call.Sender) != rlm.Previous().Address().String() {
		return makeError(errInvalidCallSender)
	}

	return nil
}

// executeCall dispatches an OP_CALL to the registered receiver's OnZkgm callback; failures and panics fail closed.
// reference: https://github.com/unionlabs/union/blob/d91c5e94354e15801bd5f82dc658eae3b79f2dad/cosmwasm/app/ucs03-zkgm/src/contract.rs#L1500-L1683
func (v *ucs03ZkgmV1) executeCall(_ int, rlm realm, packet types.Packet, relayer address, relayerMsg []byte, path *u256.Uint, call z.Call, intent bool) (types.RecvPacketResult, error) {
	// TODO: when eureka is supported, fail it closed on intent (return
	// ACK_ERR_ONLY_MAKER) like every other opcode instead of a failure ack.
	if call.Eureka {
		return callErrAck(0, rlm, makeError(errEurekaUnsupported)), nil
	}

	sender := types.CloneBytes(call.Sender)
	calldata := types.CloneBytes(call.ContractCalldata)
	receiverPath := string(call.ContractAddress)
	receiver, ok := v.store.GetReceiver(receiverPath)

	if !ok || receiver == nil {
		return callErrAck(0, rlm, makeError(errReceiverNotRegistered, receiverPath)), nil
	}

	relayerStr := string(relayer)
	proxyAccount := z.PredictCallProxyAccount(path, packet.DestinationChannelId, sender)

	// Intent settlement dispatches OnIntentZkgm to the receiver (union execute_call
	// intent arm), and is maker-only: any receiver failure reverts to ACK_ERR_ONLY_MAKER
	// so the proven recv can settle instead.
	if intent {
		env := z.IntentCallEnv{
			Caller:             relayerStr,
			ProxyAccount:       proxyAccount,
			Path:               path,
			SourceChannel:      packet.SourceChannelId.String(),
			DestinationChannel: packet.DestinationChannelId.String(),
			Sender:             sender,
			Calldata:           calldata,
			MarketMaker:        []byte(relayerStr),
			MarketMakerMsg:     types.CloneBytes(relayerMsg),
		}
		if err, panicked := safeCallOnIntentZkgm(0, rlm, receiver, env); panicked || err != nil {
			return core.NewRecvPacketResult(types.PacketStatusSuccess, types.CloneBytes(z.ACK_ERR_ONLY_MAKER)), nil
		}

		return callSuccessAck()
	}

	env := z.CallEnv{
		Caller:             relayerStr,
		ProxyAccount:       proxyAccount,
		Path:               path,
		SourceChannel:      packet.SourceChannelId.String(),
		DestinationChannel: packet.DestinationChannelId.String(),
		Sender:             sender,
		Calldata:           calldata,
		Relayer:            []byte(relayerStr),
		RelayerMsg:         types.CloneBytes(relayerMsg),
	}

	err, panicked := safeCallOnZkgm(0, rlm, receiver, env)
	if panicked {
		return core.NewRecvPacketResult(types.PacketStatusSuccess, types.CloneBytes(z.ACK_ERR_ONLY_MAKER)), nil
	}

	if err != nil {
		return callErrAck(0, rlm, err), nil
	}

	return callSuccessAck()
}

// callSuccessAck builds the empty success acknowledgement a completed call writes.
func callSuccessAck() (types.RecvPacketResult, error) {
	ack, err := z.EncodeAck(z.Ack{Tag: tagAckSuccess(), InnerAck: []byte{}})
	if err != nil {
		return core.NewRecvPacketResult(types.PacketStatusUnknown, nil), err
	}

	return core.NewRecvPacketResult(types.PacketStatusSuccess, ack), nil
}

// acknowledgeCall is a no-op for standard calls; eureka mode is unsupported.
func (v *ucs03ZkgmV1) acknowledgeCall(_ int, rlm realm, packet types.Packet, path *u256.Uint, call z.Call) error {
	if call.Eureka {
		return makeError(errEurekaUnsupported)
	}

	return nil
}

// timeoutCall is a no-op for standard calls; eureka mode is unsupported.
func (v *ucs03ZkgmV1) timeoutCall(_ int, rlm realm, packet types.Packet, path *u256.Uint, call z.Call) error {
	if call.Eureka {
		return makeError(errEurekaUnsupported)
	}

	return nil
}

// safeCallOnZkgm runs the receiver and reports a failure as panicked=true.
// revive is preferred since it also catches cross-realm aborts. The recover
// fallback, used only when revive is unsupported, catches ordinary panics.
func safeCallOnZkgm(_ int, rlm realm, receiver z.Zkgmable, env z.CallEnv) (err error, panicked bool) {
	if canRevive() {
		p := revive(func() {
			err = receiver.OnZkgm(cross(rlm), env)
		})

		return err, p != nil
	}

	defer func() {
		if recover() != nil {
			err = nil
			panicked = true
		}
	}()

	err = receiver.OnZkgm(cross(rlm), env)

	return err, false
}

// safeCallOnIntentZkgm runs the receiver's intent callback and reports a failure
// as panicked=true, mirroring safeCallOnZkgm for the OnIntentZkgm path.
func safeCallOnIntentZkgm(_ int, rlm realm, receiver z.Zkgmable, env z.IntentCallEnv) (err error, panicked bool) {
	if canRevive() {
		p := revive(func() {
			err = receiver.OnIntentZkgm(cross(rlm), env)
		})

		return err, p != nil
	}

	defer func() {
		if recover() != nil {
			err = nil
			panicked = true
		}
	}()

	err = receiver.OnIntentZkgm(cross(rlm), env)

	return err, false
}

// canRevive reports whether revive works in the current runtime. revive panics
// rather than returning when the interpreter lacks support for it.
func canRevive() (ok bool) {
	ok = true

	defer func() {
		if recover() != nil {
			ok = false
		}
	}()
	revive(func() {})

	return ok
}

// callErrAck encodes err as a failure acknowledgement for the call.
func callErrAck(_ int, rlm realm, err error) types.RecvPacketResult {
	ack, encErr := z.EncodeAck(z.Ack{Tag: tagAckFailure(), InnerAck: []byte(err.Error())})
	if encErr != nil {
		// EncodeAck on a 2-field schema is essentially infallible. A failure
		// would emit a non-Tag-prefixed ack the counterparty can't decode.
		panic(encErr)
	}

	return failureResult(ack)
}

package ucs03_zkgm

import (
	"encoding/hex"

	types "gno.land/p/onbloc/ibc/union/types"

	u256 "gno.land/p/onbloc/math/uint256"
)

// Precision invariant: channel balances are denominated in LOCAL VAULT precision —
// the actual escrowed amount held on this chain (the grc20 ledger for vouchers,
// the banker for native), 1:1 with custody — NOT the wire/counterparty precision.

// ChannelBalanceKeyV2 returns the storage key for a v2 channel balance entry.
func ChannelBalanceKeyV2(channelId types.ChannelId, path *u256.Uint, baseToken, quoteToken []byte) string {
	return channelId.String() + "/" + path.ToString() + "/" + hex.EncodeToString(baseToken) + "/" + hex.EncodeToString(quoteToken)
}

// increaseChannelBalanceV2 adds amount to the (channel, path, base, quote) escrow balance.
// reference: https://github.com/unionlabs/union/blob/d91c5e94354e15801bd5f82dc658eae3b79f2dad/cosmwasm/app/ucs03-zkgm/src/contract.rs#L3272-L3299
func (v *ucs03ZkgmV1) increaseChannelBalanceV2(_ int, rlm realm, channelId types.ChannelId, path *u256.Uint, baseToken, quoteToken []byte, amount int64) error {
	key := ChannelBalanceKeyV2(channelId, path, baseToken, quoteToken)

	curAmount, ok := v.store.GetChannelBalanceV2(key)
	if !ok || curAmount == nil {
		curAmount = u256.Zero()
	}

	amountUint256 := u256.NewUint(uint64(amount))

	// silently storing a smaller balance. This entrypoint returns no error,
	// so an overflow aborts the tx via panic.
	calculatedAmount, overflow := u256.Zero().AddOverflow(curAmount, amountUint256)
	if overflow {
		return makeError(errChannelBalanceOverflow)
	}

	v.store.SetChannelBalanceV2(0, rlm, key, calculatedAmount)

	return nil
}

// decreaseChannelBalanceV2 subtracts from the escrow balance, erroring on underflow and preserving a zero entry.
// reference: https://github.com/unionlabs/union/blob/d91c5e94354e15801bd5f82dc658eae3b79f2dad/cosmwasm/app/ucs03-zkgm/src/contract.rs#L3241-L3268
func (v *ucs03ZkgmV1) decreaseChannelBalanceV2(_ int, rlm realm, channelId types.ChannelId, path *u256.Uint, baseToken, quoteToken []byte, amount int64) error {
	key := ChannelBalanceKeyV2(channelId, path, baseToken, quoteToken)

	amountUint256 := u256.NewUint(uint64(amount))

	curAmount, ok := v.store.GetChannelBalanceV2(key)
	if !ok || curAmount == nil || curAmount.Cmp(amountUint256) < 0 {
		return makeError(errChannelBalanceUnderflow)
	}

	// This entrypoint returns an error, so an underflow aborts the tx via return.
	calculatedAmount, underflow := u256.Zero().SubOverflow(curAmount, amountUint256)
	if underflow {
		return makeError(errChannelBalanceUnderflow)
	}

	v.store.SetChannelBalanceV2(0, rlm, key, calculatedAmount)

	return nil
}

package ucs03_zkgm

import (
	"chain"
	"strconv"
	"strings"

	u256 "gno.land/p/onbloc/math/uint256"
	"gno.land/r/demo/defi/grc20reg"
)

// ibcDenomPrefix is the prefix of wrapped IBC voucher denoms (mirrors
// z.PredictWrappedToken*). Used to detect and trim wrapped denoms.
const ibcDenomPrefix = "ibc/"

const (
	// IBC_TOKEN is a zkgm-issued ibc/ voucher. Supply is minted on recv and
	// burned on send-side UNESCROW or maker burn-address ack; custody moves via
	// transferVoucher between holders and the proxy escrow.
	IBC_TOKEN = iota
	// GRC20_TOKEN is a locally registered grc20 (not a zkgm voucher). Custody
	// moves via Teller TransferFrom/Transfer; this realm cannot burn its supply.
	GRC20_TOKEN
	// NATIVE_COIN is a banker coin attached with tx -send. Escrow consumes the
	// attached funds budget; unescrow releases from the proxy banker balance.
	NATIVE_COIN
)

func isIBCTokenDenom(denom string) bool {
	return strings.HasPrefix(denom, ibcDenomPrefix)
}

func getTokenType(denom string) int {
	if isIBCTokenDenom(denom) {
		return IBC_TOKEN
	}

	if token := grc20reg.Get(denom); token != nil {
		return GRC20_TOKEN
	}

	return NATIVE_COIN
}

// parseCoins parses a comma-separated <amount><denom> string into Coins.
func parseCoins(s string) chain.Coins {
	if s == "" {
		return nil
	}

	parts := strings.Split(s, ",")
	coins := make([]chain.Coin, 0, len(parts))

	for _, part := range parts {
		if part == "" {
			continue
		}

		i := 0
		for i < len(part) && part[i] >= '0' && part[i] <= '9' {
			i++
		}

		if i == 0 || i == len(part) {
			panic("zkgm/coins: invalid coin " + part)
		}

		amount, err := strconv.ParseInt(part[:i], 10, 64)
		if err != nil {
			panic(err)
		}

		coins = append(coins, chain.NewCoin(part[i:], amount))
	}

	return chain.NewCoins(coins...)
}

// funds is the gno analog of the reference contract's threaded `funds: &mut Coins`
// (the message's attached coins). It is decremented as each token order consumes
// its BaseAmount during verification.
type funds struct {
	coins map[string]chain.Coin
}

// newFunds snapshots the attached coins into a mutable spend budget.
func newFunds(sent chain.Coins) *funds {
	f := &funds{coins: make(map[string]chain.Coin)}

	for _, coin := range sent {
		f.coins[coin.Denom] = coin
	}

	return f
}

// sub deducts amount of denom from the attached funds, mirroring funds.sub(coin)
// in the reference contract. It errors when the funds do not cover the amount.
func (f *funds) sub(denom string, amount *u256.Uint) error {
	want, err := amountInt64(amount)
	if err != nil {
		return err
	}

	coin, ok := f.coins[denom]
	if !ok {
		return makeError(errCoinMismatch)
	}

	if coin.Amount < want {
		return makeError(errCoinMismatch)
	}

	coin.Amount -= want
	f.coins[denom] = coin

	return nil
}

// isEmpty reports whether every attached coin has been fully consumed.
func (f *funds) isEmpty() bool {
	for _, coin := range f.coins {
		if coin.Amount != 0 {
			return false
		}
	}

	return true
}

// assertEmpty errors when any attached coin is left unconsumed.
func (f *funds) assertEmpty() error {
	if !f.isEmpty() {
		return makeError(errCoinMismatch)
	}

	return nil
}

package ucs03_zkgm

import (
	"bytes"

	types "gno.land/p/onbloc/ibc/union/types"

	"gno.land/p/nt/ufmt/v0"
	z "gno.land/p/onbloc/ibc/union/zkgm"
	u256 "gno.land/p/onbloc/math/uint256"
	core "gno.land/r/onbloc/ibc/union/core"
)

// verifyInternal routes an instruction to its opcode-specific verifier (the send-side validation entry point).
// reference: https://github.com/unionlabs/union/blob/d91c5e94354e15801bd5f82dc658eae3b79f2dad/cosmwasm/app/ucs03-zkgm/src/contract.rs#L2742-L2796
func (v *ucs03ZkgmV1) verifyInternal(_ int, rlm realm, funds *funds, channelId types.ChannelId, path *u256.Uint, instruction z.Instruction) error {
	switch instruction.Opcode {
	case z.OP_TOKEN_ORDER:
		order, err := decodeOrderInstruction(instruction)
		if err != nil {
			return err
		}

		return v.verifyTokenOrderV2(0, rlm, funds, channelId, path, order)
	case z.OP_BATCH:
		batch, err := decodeBatchInstruction(instruction)
		if err != nil {
			return err
		}

		return v.verifyBatch(0, rlm, funds, channelId, path, batch)
	case z.OP_FORWARD:
		forward, err := decodeForwardInstruction(instruction)
		if err != nil {
			return err
		}

		return v.verifyForward(0, rlm, funds, channelId, forward)
	case z.OP_CALL:
		call, err := decodeCallInstruction(instruction)
		if err != nil {
			return err
		}

		return v.verifyCall(0, rlm, call)
	default:
		return makeError(errUnsupportedOpcode)
	}
}

// execFatal is a sentinel panic value.
//
// Unlike ordinary panics, values of this type are re-panicked by the recover
// handler so the VM can observe the failure after transaction rollback.
type execFatal struct{ msg string }

func (e execFatal) Error() string { return e.msg }

// dispatchExecutePacket routes a received instruction to its opcode handler, turning non-fatal errors into a failure ack.
func (v *ucs03ZkgmV1) dispatchExecutePacket(
	_ int, rlm realm,
	packet types.Packet,
	relayer address,
	relayerMsg []byte,
	salt [32]byte,
	path *u256.Uint,
	instruction z.Instruction,
	intent bool,
) (result types.RecvPacketResult, err error) {
	defer func() {
		if r := recover(); r != nil {
			if _, ok := r.(execFatal); ok {
				panic(r)
			}

			result = failureResult(universalErrorAck())
			err = nil
		}
	}()

	switch instruction.Opcode {
	case z.OP_TOKEN_ORDER:
		order, err := decodeOrderInstruction(instruction)
		if err != nil {
			return core.NewRecvPacketResult(types.PacketStatusUnknown, nil), err
		}

		return v.executeTokenOrderV2(0, rlm, packet, relayer, relayerMsg, salt, path, order, intent)
	case z.OP_BATCH:
		batch, err := decodeBatchInstruction(instruction)
		if err != nil {
			return core.NewRecvPacketResult(types.PacketStatusUnknown, nil), err
		}

		ack, err := v.executeBatch(0, rlm, packet, relayer, relayerMsg, salt, path, batch, intent)
		if err != nil {
			return core.NewRecvPacketResult(types.PacketStatusUnknown, nil), err
		}

		return core.NewRecvPacketResult(types.PacketStatusSuccess, ack), nil
	case z.OP_CALL:
		call, err := decodeCallInstruction(instruction)
		if err != nil {
			return core.NewRecvPacketResult(types.PacketStatusUnknown, nil), err
		}

		return v.executeCall(0, rlm, packet, relayer, relayerMsg, path, call, intent)
	case z.OP_FORWARD:
		forward, err := decodeForwardInstruction(instruction)
		if err != nil {
			return core.NewRecvPacketResult(types.PacketStatusUnknown, nil), err
		}

		return v.executeForward(0, rlm, packet, salt, path, forward, intent)
	default:
		return core.NewRecvPacketResult(types.PacketStatusUnknown, nil), makeError(errUnsupportedOpcode)
	}
}

// acknowledgeInternal routes an acknowledgement to its opcode handler.
func (v *ucs03ZkgmV1) acknowledgeInternal(_ int, rlm realm, packet types.Packet, relayer address, salt [32]byte, path *u256.Uint, instruction z.Instruction, successful bool, ack []byte) error {
	switch instruction.Opcode {
	case z.OP_TOKEN_ORDER:
		order, err := decodeOrderInstruction(instruction)
		if err != nil {
			return err
		}

		var orderAck z.TokenOrderAck

		hasOrderAck := false

		if successful {
			decoded, err := z.DecodeTokenOrderAck(ack)
			if err != nil {
				return err
			}

			orderAck = decoded
			hasOrderAck = true
		}

		return v.acknowledgeTokenOrderV2(0, rlm, packet, relayer, salt, path, order, orderAck, hasOrderAck)
	case z.OP_BATCH:
		batch, err := decodeBatchInstruction(instruction)
		if err != nil {
			return err
		}

		return v.acknowledgeBatch(0, rlm, packet, relayer, salt, path, batch, successful, ack)
	case z.OP_CALL:
		call, err := decodeCallInstruction(instruction)
		if err != nil {
			return err
		}

		return v.acknowledgeCall(0, rlm, packet, path, call)
	default:
		return makeError(errUnsupportedOpcode)
	}
}

// timeoutInternal routes a timeout to its opcode handler.
func (v *ucs03ZkgmV1) timeoutInternal(_ int, rlm realm, packet types.Packet, salt [32]byte, path *u256.Uint, instruction z.Instruction) error {
	switch instruction.Opcode {
	case z.OP_TOKEN_ORDER:
		order, err := decodeOrderInstruction(instruction)
		if err != nil {
			return err
		}

		return v.refundV2(0, rlm, path, packet.SourceChannelId, order)
	case z.OP_BATCH:
		batch, err := decodeBatchInstruction(instruction)
		if err != nil {
			return err
		}

		return v.timeoutBatch(0, rlm, packet, salt, path, batch)
	case z.OP_CALL:
		call, err := decodeCallInstruction(instruction)
		if err != nil {
			return err
		}

		return v.timeoutCall(0, rlm, packet, path, call)
	default:
		return makeError(errUnsupportedOpcode)
	}
}

// decodeOrderInstruction decodes a v2 token order, rejecting unsupported instruction versions.
func decodeOrderInstruction(instruction z.Instruction) (z.TokenOrderV2, error) {
	if instruction.Version != z.INSTR_VERSION_2 {
		return z.TokenOrderV2{}, makeError(errUnsupportedTokenOrderVersion)
	}

	return z.DecodeTokenOrderV2(instruction.Operand)
}

// decodeCallInstruction decodes a call, rejecting unsupported instruction versions.
func decodeCallInstruction(instruction z.Instruction) (z.Call, error) {
	if instruction.Version != z.INSTR_VERSION_0 {
		return z.Call{}, makeError(errUnsupportedCallVersion)
	}

	return z.DecodeCall(instruction.Operand)
}

// decodeBatchInstruction decodes a batch, rejecting unsupported instruction versions.
func decodeBatchInstruction(instruction z.Instruction) (z.Batch, error) {
	if instruction.Version != z.INSTR_VERSION_0 {
		return z.Batch{}, makeError(errUnsupportedBatchVersion)
	}

	return z.DecodeBatch(instruction.Operand)
}

// decodeForwardInstruction decodes a forward, rejecting unsupported instruction versions.
func decodeForwardInstruction(instruction z.Instruction) (z.Forward, error) {
	if instruction.Version != z.INSTR_VERSION_0 {
		return z.Forward{}, makeError(errUnsupportedForwardVersion)
	}

	return z.DecodeForward(instruction.Operand)
}

// mustEncodeUniversalErrorAck returns the ABI-encoded failure acknowledgement
// `z.Ack{Tag: TAG_ACK_FAILURE, InnerAck: empty}` that zkgm-internal recv failures
// emit. The empty inner ack matches union's `Ack{tag: TAG_ACK_FAILURE, inner_ack:
// Default::default()}`; the encoded Ack itself is non-empty, satisfying core's
// non-empty acknowledgement requirement.
func mustEncodeUniversalErrorAck() []byte {
	bz, err := z.EncodeAck(z.Ack{
		Tag:      u256.NewUint(0),
		InnerAck: []byte{},
	})
	if err != nil {
		panic(err)
	}

	return bz
}

// failureResult wraps an ack as a failed recv result.
func failureResult(ack []byte) types.RecvPacketResult {
	return core.NewRecvPacketResult(types.PacketStatusFailure, ack)
}

// universalErrorAck returns the cached sentinel error acknowledgement.
func universalErrorAck() []byte {
	return mustEncodeUniversalErrorAck()
}

// tokenOrderDestinationChannel rejects the zero-channel sentinel so the
// derived destChan is safe to feed into UpdateChannelPath / PopChannelFromPath
// without colliding with the "no channel" slot. This mirrors the TokenOrder
// path helper's channel-zero rejection.
func tokenOrderDestinationChannel(channelId types.ChannelId) (uint32, error) {
	raw := uint32(channelId)
	if raw == 0 {
		return 0, makeError(errInvalidTokenOrderDestChannel)
	}

	return raw, nil
}

// isOnlyMakerAck reports whether ack is the only-maker sentinel.
func isOnlyMakerAck(ack []byte) bool {
	return bytes.Equal(ack, z.ACK_ERR_ONLY_MAKER)
}

// extractPanicMessage renders a recovered panic value as a string.
func extractPanicMessage(r any) string {
	switch v := r.(type) {
	case string:
		return v
	case error:
		return v.Error()
	default:
		return ufmt.Sprintf("%v", v)
	}
}

package ucs03_zkgm

import (
	"errors"
	"strings"
)

// Error messages for the zkgm v1 impl, collected in one place so the wording
// stays consistent. They are string constants rather than package-level error

// values; build them with makeError at the call site (see above).
const (
	// opcode routing
	errUnsupportedOpcode = "unsupported opcode"

	// instruction decoding
	errUnsupportedTokenOrderVersion = "unsupported token order version"
	errUnsupportedCallVersion       = "unsupported call version"
	errUnsupportedBatchVersion      = "unsupported batch version"
	errUnsupportedForwardVersion    = "unsupported forward version"

	// token order
	errInvalidUnescrow                    = "invalid token order unescrow"
	errTokenOrderFeeUnderflow             = "token order fee underflow: quote amount exceeds base amount"
	errUnknownTokenOrderKind              = "unknown token order kind"
	errUnknownFillType                    = "unknown fill type"
	errUnsupportedTokenOrderKindForAck    = "unsupported token order kind for ack"
	errUnsupportedTokenOrderKindForRefund = "unsupported token order kind for refund"
	errSolveNotImplemented                = "solve token order not implemented"
	errInvalidTokenOrderDestChannel       = "invalid token order destination channel"
	errInvalidTokenOrderTransferAmount    = "invalid token order transfer amount"

	// errMetadataDecimalsMismatch guards an INITIALIZE order's declared
	// metadata decimals against the locally-known ground truth for its base
	// denom (a registered grc20's real decimals, or a held voucher's recorded
	// OriginDecimals when forwarding it onward). Left unchecked, the
	// counterparty (or next hop) would deploy/interpret the wrapped copy at
	// the wrong precision even though the raw amount moved correctly here.
	errMetadataDecimalsMismatch = "token order: metadata decimals do not match the local token"

	// call
	errEurekaUnsupported     = "eureka mode not supported"
	errInvalidCallSender     = "invalid call sender"
	errReceiverNotRegistered = "receiver not registered"
	errIsOnlyMakerAck        = "is only maker ack"

	// forward
	errInvalidForwardInstruction = "invalid forward instruction"
	errForwardMissingPrevDest    = "forward missing previous destination channel"
	errForwardMissingNextSource  = "forward missing next source channel"
	errForwardPrevDestMismatch   = "forward previous-destination mismatch"
	errForwardZeroTimeout        = "forward timeout timestamp must be non-zero"

	// batch
	errInvalidBatchInstruction = "invalid batch instruction"
	errBatchAckCountMismatch   = "batch ack count mismatch"

	// voucher
	errAmountOverflow                 = "amount overflows int64"
	errVoucherNotFound                = "voucher not found"
	errVoucherSymbolAlreadyRegistered = "voucher symbol already registered under a different denom"

	// rate limit
	errTokenBucketAbsent = "token bucket is absent"

	// coins / channel balance
	errCoinMismatch            = "zkgm/coins: sent coin mismatch"
	errChannelBalanceUnderflow = "zkgm/channel_balance: underflow"
	errChannelBalanceOverflow  = "zkgm/channel_balance: overflow"

	// ErrSpoofedRealm guards non-crossing (_ int, rlm realm, ...) entrypoints: the
	// passed rlm must be the current crossing frame, not a forged or stale token.
	errSpoofedRealm = "rlm does not match the current crossing frame"
)

func makeError(msgs ...string) error {
	return errors.New(strings.Join(msgs, ", "))
}

package ucs03_zkgm

import (
	"chain"
	"chain/banker"

	u256 "gno.land/p/onbloc/math/uint256"
	zkgm "gno.land/r/onbloc/ibc/union/apps/ucs03_zkgm"
)

// sendNative releases `amount` of denom from the proxy escrow account to
// receiver. Escrowed native funds sit at the proxy realm address; under the
// interrealm borrow rule this banker send executes in the proxy's ownership
// context even though it is invoked from the impl call frame, so the funds leave
// the proxy escrow rather than the impl realm.
func (v *ucs03ZkgmV1) sendNative(_ int, rlm realm, denom string, receiver address, amount *u256.Uint) error {
	n, err := amountInt64(amount)
	if err != nil {
		return err
	}
	// rlm.Address() is the proxy escrow account: under the interrealm borrow rule
	// the impl operates in the proxy's ownership context, so the realm-send banker
	// draws from the proxy balance where the user's -send funds landed.
	b := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	b.SendCoins(rlm.Address(), receiver, chain.NewCoins(chain.NewCoin(denom, n)))
	zkgm.EmitNativeReleased(0, rlm, denom, receiver, n)

	return nil
}

package ucs03_zkgm

import (
	types "gno.land/p/onbloc/ibc/union/types"

	z "gno.land/p/onbloc/ibc/union/zkgm"
	u256 "gno.land/p/onbloc/math/uint256"
	zkgm "gno.land/r/onbloc/ibc/union/apps/ucs03_zkgm"
	core "gno.land/r/onbloc/ibc/union/core"
)

// verifyForward checks the forwarded instruction is allowed and the timeout is set, then verifies the inner instruction.
// reference: https://github.com/unionlabs/union/blob/d91c5e94354e15801bd5f82dc658eae3b79f2dad/cosmwasm/app/ucs03-zkgm/src/contract.rs#L2969-L2995
func (v *ucs03ZkgmV1) verifyForward(_ int, rlm realm, funds *funds, channelId types.ChannelId, forward z.Forward) error {
	if !isAllowedForwardInstruction(forward.Instruction.Opcode) {
		return makeError(errInvalidForwardInstruction)
	}

	if forward.TimeoutTimestamp == 0 {
		return makeError(errForwardZeroTimeout)
	}

	return v.verifyInternal(0, rlm, funds, channelId, forward.Path, forward.Instruction)
}

// executeForward builds and dispatches the next-hop packet, recording the parent for async ack settlement.
// reference: https://github.com/unionlabs/union/blob/d91c5e94354e15801bd5f82dc658eae3b79f2dad/cosmwasm/app/ucs03-zkgm/src/contract.rs#L1392-L1497
func (v *ucs03ZkgmV1) executeForward(_ int, rlm realm, packet types.Packet, salt [32]byte, path *u256.Uint, forward z.Forward, intent bool) (types.RecvPacketResult, error) {
	// Recv bypasses verifyInternal (see imp.gno OnRecvPacket flow),
	// receive-side opcode check is the only enforcement point.
	// Do not remove it as redundant with verifyForward.
	if !isAllowedForwardInstruction(forward.Instruction.Opcode) {
		return core.NewRecvPacketResult(types.PacketStatusUnknown, nil), makeError(errInvalidForwardInstruction)
	}

	if intent {
		return core.NewRecvPacketResult(types.PacketStatusSuccess, types.CloneBytes(z.ACK_ERR_ONLY_MAKER)), nil
	}

	childPacket, err := buildForwardChild(packet, path, salt, forward)
	if err != nil {
		return core.NewRecvPacketResult(types.PacketStatusUnknown, nil), err
	}

	// Forward children build ZkgmPacket directly. Their salt is derived with
	// DeriveForwardSalt, not DeriveSenderSalt. Route the child through core so
	// it receives a normal packet commitment, then track its parent so child
	// resolution can write the deferred parent ack.
	childPacket = core.SendPacket(cross(rlm), childPacket.SourceChannelId, childPacket.TimeoutTimestamp, childPacket.Data)
	childHash := types.MustCommit(types.CommitPacket(childPacket))
	v.store.SetInFlightPacket(0, rlm, childHash.String(), packet)
	zkgm.EmitForwardInFlightSet(0, rlm, childHash, types.MustCommit(types.CommitPacket(packet)))

	return core.NewRecvPacketResult(types.PacketStatusAsync, nil), nil
}

// handleForwardChild detects a forwarded child packet resolving on ack/timeout
// and writes the captured parent's deferred acknowledgement through core.
func (v *ucs03ZkgmV1) handleForwardChild(_ int, rlm realm, packet types.Packet, zp z.ZkgmPacket, ack []byte) bool {
	if !z.IsForwardedPacket(zp.Salt) {
		return false
	}

	key := forwardInFlightKey(packet)

	parent, ok := v.store.GetInFlightPacket(key)
	if !ok {
		zkgm.EmitForwardInFlightPopped(0, rlm, types.MustCommit(types.CommitPacket(packet)), false)
		return false
	}

	v.store.RemoveInFlightPacket(0, rlm, key)
	zkgm.EmitForwardInFlightPopped(0, rlm, types.MustCommit(types.CommitPacket(packet)), true)
	core.WriteAcknowledgement(cross(rlm), types.NewMsgWriteAcknowledgement(parent, ack))

	return true
}

// forwardInFlightKey derives the in-flight key from the child packet's commitment hash.
func forwardInFlightKey(packet types.Packet) string {
	return types.MustCommit(types.CommitPacket(packet)).String()
}

// buildForwardChild builds the next-hop packet, advancing the channel path and namespacing the salt.
func buildForwardChild(packet types.Packet, path *u256.Uint, parentSalt [32]byte, forward z.Forward) (types.Packet, error) {
	if forward.TimeoutTimestamp == 0 {
		return core.NewPacket(0, 0, nil, 0), makeError(errForwardZeroTimeout)
	}

	tailPath, prevDestChannel := z.DequeueChannelFromPath(forward.Path)
	if prevDestChannel == 0 {
		return core.NewPacket(0, 0, nil, 0), makeError(errForwardMissingPrevDest)
	}

	continuationPath, nextSourceChannel := z.DequeueChannelFromPath(tailPath)
	if nextSourceChannel == 0 {
		return core.NewPacket(0, 0, nil, 0), makeError(errForwardMissingNextSource)
	}

	if packet.DestinationChannelId != types.ChannelId(prevDestChannel) {
		return core.NewPacket(0, 0, nil, 0), makeError(errForwardPrevDestMismatch)
	}

	nextInstruction := forward.Instruction

	if !continuationPath.IsZero() {
		nextForward := z.Forward{
			Path:             continuationPath,
			TimeoutHeight:    0,
			TimeoutTimestamp: forward.TimeoutTimestamp,
			Instruction:      forward.Instruction,
		}

		forwardBytes, err := z.EncodeForward(nextForward)
		if err != nil {
			return core.NewPacket(0, 0, nil, 0), err
		}

		nextInstruction = z.Instruction{
			Version: z.INSTR_VERSION_0,
			Opcode:  z.OP_FORWARD,
			Operand: forwardBytes,
		}
	}

	intermediate, err := z.UpdateChannelPath(path, prevDestChannel)
	if err != nil {
		return core.NewPacket(0, 0, nil, 0), err
	}

	nextPath, err := z.UpdateChannelPath(intermediate, nextSourceChannel)
	if err != nil {
		return core.NewPacket(0, 0, nil, 0), err
	}

	childBytes, err := z.EncodeZkgmPacket(z.ZkgmPacket{
		Salt:        z.DeriveForwardSalt(parentSalt),
		Path:        nextPath,
		Instruction: nextInstruction,
	})
	if err != nil {
		return core.NewPacket(0, 0, nil, 0), err
	}

	sourceChannelId := types.ChannelId(nextSourceChannel)
	sourceChannel, err := core.GetChannel(sourceChannelId)
	if err != nil {
		return core.NewPacket(0, 0, nil, 0), err
	}

	return core.NewPacket(sourceChannelId, sourceChannel.CounterpartyChannelId, childBytes, types.Timestamp(forward.TimeoutTimestamp)), nil
}

// isAllowedForwardInstruction reports whether opcode may be forwarded.
func isAllowedForwardInstruction(opcode uint8) bool {
	return opcode == z.OP_CALL || opcode == z.OP_TOKEN_ORDER || opcode == z.OP_BATCH
}

package ucs03_zkgm

import (
	types "gno.land/p/onbloc/ibc/union/types"
	tb "gno.land/p/onbloc/ibc/union/zkgm/tokenbucket"
	u256 "gno.land/p/onbloc/math/uint256"
	zkgm "gno.land/r/onbloc/ibc/union/apps/ucs03_zkgm"
)

// getters.gno implements the read-only IAppGetter surface. Results read the
// injected proxy store and return snapshots so callers do not receive mutable
// proxy-owned pointers.

// GetTokenBucket returns the rate-limit bucket configured for denom.
func (v *ucs03ZkgmV1) GetTokenBucket(denom string) (*tb.TokenBucket, error) {
	bucket, ok := v.store.GetTokenBucket(denom)
	if !ok || bucket == nil {
		return nil, makeError(zkgm.ErrTokenBucketNotFound, denom)
	}

	return cloneTokenBucket(bucket), nil
}

// GetChannelBalanceV2 returns the escrow balance for the v2 channel-balance key.
func (v *ucs03ZkgmV1) GetChannelBalanceV2(channelId types.ChannelId, path *u256.Uint, baseToken string, quoteToken []byte) (*u256.Uint, error) {
	balance, ok := v.store.GetChannelBalanceV2(ChannelBalanceKeyV2(channelId, path, []byte(baseToken), quoteToken))
	if !ok || balance == nil {
		return nil, makeError(zkgm.ErrChannelBalanceV2NotFound, channelId.String())
	}

	return balance.Clone(), nil
}

// GetLockedTokenAmount returns the terminally locked base-token amount for denom.
func (v *ucs03ZkgmV1) GetLockedTokenAmount(denom string) (*u256.Uint, error) {
	total, ok := v.store.GetLockedTokenAmount(denom)
	if !ok || total == nil {
		return u256.Zero(), nil
	}

	return total.Clone(), nil
}

// GetVoucherList returns a page of up to count wrapped voucher tokens starting
// at offset, ordered by denom. An empty page (e.g. offset past the end, or no
// vouchers registered yet) is not an error condition, so this returns an empty
// slice rather than failing; the error return exists only to match the
// calling convention shared by every other IAppGetter method and is always nil.
func (v *ucs03ZkgmV1) GetVoucherList(offset, count int) ([]zkgm.VoucherInfo, error) {
	return v.store.GetVoucherList(offset, count), nil
}

// GetVoucherSize returns the total number of registered vouchers. Like
// GetVoucherList, the error return exists only to match the calling
// convention shared by every other IAppGetter method and is always nil.
func (v *ucs03ZkgmV1) GetVoucherSize() (int, error) {
	return v.store.GetVoucherSize(), nil
}

// GetVoucherInfo returns a snapshot of the single wrapped voucher registered
// for ibcDenom. Unlike GetVoucherList, the caller already holds the key, so
// this reads Store.GetVoucher directly and converts via the voucher's public
// (capability-free) accessors instead of adding a Store-level method.
func (v *ucs03ZkgmV1) GetVoucherInfo(ibcDenom string) (zkgm.VoucherInfo, error) {
	vou, ok := v.store.GetVoucher(ibcDenom)
	if !ok || vou == nil {
		return zkgm.NewVoucherInfo("", "", "", 0, 0, 0), makeError(errVoucherNotFound, ibcDenom)
	}

	return zkgm.NewVoucherInfo(
		ibcDenom,
		vou.Token().GetName(),
		vou.Token().GetSymbol(),
		vou.OriginDecimals(),
		uint8(vou.Token().GetDecimals()),
		vou.Token().TotalSupply(),
	), nil
}

func cloneTokenBucket(bucket *tb.TokenBucket) *tb.TokenBucket {
	return &tb.TokenBucket{
		Capacity:   bucket.Capacity.Clone(),
		Available:  bucket.Available.Clone(),
		RefillRate: bucket.RefillRate.Clone(),
		LastRefill: bucket.LastRefill.Clone(),
	}
}

package ucs03_zkgm

import (
	"chain/runtime/unsafe"

	types "gno.land/p/onbloc/ibc/union/types"

	z "gno.land/p/onbloc/ibc/union/zkgm"
	u256 "gno.land/p/onbloc/math/uint256"
	zkgm "gno.land/r/onbloc/ibc/union/apps/ucs03_zkgm"
	"gno.land/r/onbloc/ibc/union/core"
)

// ucs03ZkgmV1 is the v1 implementation of the zkgm app. It holds the injected
// proxy state (zkgm.IStore) and contains all the protocol logic; the proxy keeps
// only the stable identity, the escrow funds, and the swap point. State writes go
// through the store's borrow-rule setters: v.store.SetXXX(0, rlm, ...).
type ucs03ZkgmV1 struct {
	store zkgm.IStore
}

var _ zkgm.IApp = &ucs03ZkgmV1{}

// NewUCS03ZkgmV1 constructs a fresh v1 impl bound to the injected store.
func NewUCS03ZkgmV1(store zkgm.IStore) zkgm.IApp {
	return &ucs03ZkgmV1{store: store}
}

// OnChannelOpenInit accepts a channel only if it speaks the zkgm protocol version.
func (v *ucs03ZkgmV1) OnChannelOpenInit(_ int, rlm realm, connectionId types.ConnectionId, channelId types.ChannelId, version string, relayer address) {
	assertIsRlmCurrent(0, rlm)

	enforceVersion(version)
}

// OnChannelOpenTry enforces the protocol version on both sides of the handshake.
func (v *ucs03ZkgmV1) OnChannelOpenTry(_ int, rlm realm, connectionId types.ConnectionId, channelId types.ChannelId, version string, counterpartyVersion string, relayer address) {
	assertIsRlmCurrent(0, rlm)

	enforceVersion(version)
	enforceVersion(counterpartyVersion)
}

// OnChannelOpenAck enforces the counterparty's negotiated protocol version.
func (v *ucs03ZkgmV1) OnChannelOpenAck(_ int, rlm realm, channelId types.ChannelId, counterpartyChannelId types.ChannelId, counterpartyVersion string, relayer address) {
	assertIsRlmCurrent(0, rlm)

	enforceVersion(counterpartyVersion)
}

// OnChannelOpenConfirm completes the handshake; zkgm keeps no per-channel state.
func (v *ucs03ZkgmV1) OnChannelOpenConfirm(_ int, rlm realm, channelId types.ChannelId, relayer address) {
	assertIsRlmCurrent(0, rlm)
}

// Channel closing is not supported by zkgm (reference returns an error).
func (v *ucs03ZkgmV1) OnChannelCloseInit(_ int, rlm realm, channelId types.ChannelId, relayer address) {
	assertIsRlmCurrent(0, rlm)

	panic("channel closing is not allowed")
}

func (v *ucs03ZkgmV1) OnChannelCloseConfirm(_ int, rlm realm, channelId types.ChannelId, relayer address) {
	assertIsRlmCurrent(0, rlm)

	panic("channel closing is not allowed")
}

// OnRecvPacket decodes the packet and dispatches it; decode/exec failures return a failure ack rather than aborting.
func (v *ucs03ZkgmV1) OnRecvPacket(_ int, rlm realm, packet types.Packet, relayer address, relayerMsg []byte) types.RecvPacketResult {
	assertIsRlmCurrent(0, rlm)

	zp, err := z.DecodeZkgmPacket(types.CloneBytes(packet.Data))
	if err != nil {
		zkgm.EmitRecvError(0, rlm, packet.SourceChannelId, packet.DestinationChannelId, err.Error())
		return failureResult(universalErrorAck())
	}

	res, err := v.dispatchExecutePacket(0, rlm, packet, relayer, relayerMsg, zp.Salt, zp.Path, zp.Instruction, false)
	if err != nil {
		zkgm.EmitRecvError(0, rlm, packet.SourceChannelId, packet.DestinationChannelId, err.Error())
		return failureResult(universalErrorAck())
	}

	// An only-maker outcome (a maker-only fill that could not be satisfied, or
	// an only-maker child anywhere in a batch) must revert the whole recv tx —
	// no ack is written and any already-applied batch-child mutations are rolled
	// back. This mirrors union's reply handler returning Err(OnlyMaker) for both
	// the single-instruction and batch cases (contract.rs L2530, L2545), and the
	// symmetric guard already in OnIntentRecvPacket. Core does not recover recv
	// panics, so this reverts atomically.
	if isOnlyMakerAck(res.Acknowledgement) {
		panic(errIsOnlyMakerAck)
	}

	return res
}

// OnIntentRecvPacket executes the market-maker fast path. Only-maker outcomes
// abort the intent tx so proven recv can proceed instead. This is also the
// explicit stop point for market-maker fills that require unsupported native
// maker funding.
func (v *ucs03ZkgmV1) OnIntentRecvPacket(_ int, rlm realm, packet types.Packet, marketMaker address, marketMakerMsg []byte) types.RecvPacketResult {
	assertIsRlmCurrent(0, rlm)

	zp, err := z.DecodeZkgmPacket(types.CloneBytes(packet.Data))
	if err != nil {
		zkgm.EmitRecvError(0, rlm, packet.SourceChannelId, packet.DestinationChannelId, err.Error())
		return failureResult(universalErrorAck())
	}

	res, err := v.dispatchExecutePacket(0, rlm, packet, marketMaker, marketMakerMsg, zp.Salt, zp.Path, zp.Instruction, true)
	if err != nil {
		zkgm.EmitRecvError(0, rlm, packet.SourceChannelId, packet.DestinationChannelId, err.Error())
		return failureResult(universalErrorAck())
	}

	if isOnlyMakerAck(res.Acknowledgement) {
		// Intent recv must not silently succeed without a maker fill. Panicking
		// preserves the proven recv fallback path and makes unsupported native
		// market-maker funding fail explicitly until funds plumbing is added.
		panic("only maker")
	}

	return res
}

// OnAcknowledgementPacket routes the ack to its instruction, or to the forwarded parent packet.
func (v *ucs03ZkgmV1) OnAcknowledgementPacket(_ int, rlm realm, packet types.Packet, acknowledgement []byte, relayer address) {
	assertIsRlmCurrent(0, rlm)

	zp, err := z.DecodeZkgmPacket(types.CloneBytes(packet.Data))
	if err != nil {
		panic(err.Error())
	}

	if v.handleForwardChild(0, rlm, packet, zp, acknowledgement) {
		return
	}

	outerAck, err := z.DecodeAck(acknowledgement)
	if err != nil {
		panic(err.Error())
	}

	successful := outerAck.Tag != nil && outerAck.Tag.Eq(tagAckSuccess())
	if err := v.acknowledgeInternal(0, rlm, packet, relayer, zp.Salt, zp.Path, zp.Instruction, successful, outerAck.InnerAck); err != nil {
		panic(err.Error())
	}
}

// OnTimeoutPacket refunds the timed-out instruction, or settles the forwarded parent packet.
func (v *ucs03ZkgmV1) OnTimeoutPacket(_ int, rlm realm, packet types.Packet, relayer address) {
	assertIsRlmCurrent(0, rlm)

	zp, err := z.DecodeZkgmPacket(types.CloneBytes(packet.Data))
	if err != nil {
		panic(err.Error())
	}

	if v.handleForwardChild(0, rlm, packet, zp, universalErrorAck()) {
		return
	}

	if err := v.timeoutInternal(0, rlm, packet, zp.Salt, zp.Path, zp.Instruction); err != nil {
		panic(err.Error())
	}
}

// Send verifies the instruction against the attached funds, namespaces the salt, and emits the packet through core.
func (v *ucs03ZkgmV1) Send(_ int, rlm realm, channelId types.ChannelId, timeoutTimestamp types.Timestamp, salt [32]byte, instruction z.Instruction) types.Packet {
	assertIsRlmCurrent(0, rlm)

	sender := rlm.Previous().Address().String()

	funds := newFunds(parseCoins(""))

	// SAFE: native coins attached with -send live on the chain-root envelope,
	// not on rlm.Previous(). Guard direct user calls before reading
	// unsafe.OriginSend(), then seed the proxy escrow budget from it.
	if rlm.Previous().IsUserCall() {
		sentCoins := unsafe.OriginSend()
		funds = newFunds(sentCoins)
	}

	err := v.verifyInternal(0, rlm, funds, channelId, u256.Zero(), instruction)
	if err != nil {
		panic(err)
	}

	err = funds.assertEmpty()
	if err != nil {
		panic(err)
	}

	// Only user-initiated sends apply DeriveSenderSalt. Forwarded packets are
	// built in forward.gno and use DeriveForwardSalt instead.
	hashedSalt := z.DeriveSenderSalt([]byte(sender), salt)

	data, err := z.EncodeZkgmPacket(z.ZkgmPacket{
		Salt:        hashedSalt,
		Path:        u256.Zero(),
		Instruction: instruction,
	})
	if err != nil {
		panic(err)
	}

	return core.SendPacket(cross(rlm), channelId, timeoutTimestamp, data)
}

// enforceVersion rejects channels that do not speak the zkgm protocol version.
func enforceVersion(version string) {
	if version != zkgm.Version {
		panic("unsupported channel version")
	}
}

